export const RAHPC_ANAES_MOCKS: TestDef[] = [
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-anaesthesia-licensing-exam","name":"Anaesthesia Licensing Exam (RAHPC)"},
    slug: "rahpc-anaesthesia-mock-exam-1",
    title: "Anaesthesia Licensing Exam (RAHPC) — Mock Exam 1",
    summary: "Anaesthetic Pharmacology and General Anaesthesia; Regional Anaesthesia, Critical Care and Resuscitation.",
    free: true, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover anaesthesia practice."],
    sections: [{"name":"Anaesthetic Pharmacology and General Anaesthesia"},{"name":"Regional Anaesthesia, Critical Care and Resuscitation"}],
    questions: [
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Propofol Haemodynamic Effects","stem":"A 45-year-old healthy man receives propofol 2 mg/kg for induction. His blood pressure falls from 130/80 to 88/50 mmHg. What is the main cause of this fall?","options":["Vagal stimulation causing severe bradycardia","Histamine release causing widespread flushing","Acute adrenal suppression caused by the drug","Vasodilation with a fall in systemic vascular resistance"],"correct":3,"explanation":"Propofol lowers blood pressure mainly by arterial and venous dilation (lower systemic vascular resistance and preload), with some myocardial depression and a blunted baroreflex. It releases very little histamine and the heart rate usually changes little, so bradycardia is not the main cause."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Hypertension Before Elective Surgery","stem":"A 58-year-old man is seen in the pre-assessment clinic two weeks before an elective hernia repair. He has no symptoms, but his blood pressure is 186/114 mmHg on repeated readings. What is the best plan?","options":["Postpone the surgery and refer him to get his blood pressure controlled first","Proceed as planned and treat the blood pressure in recovery","Proceed under spinal anaesthesia so that laryngoscopy is avoided","Give oral nifedipine on the day and proceed once the reading falls"],"correct":0,"explanation":"AAGBI and British Hypertension Society guidance advises that a clinic blood pressure of 180/110 mmHg or more should be controlled before elective surgery, because it raises the risk of perioperative stroke, myocardial ischaemia and large swings in blood pressure. Changing to a spinal or giving a quick dose of a drug on the day does not treat the uncontrolled hypertension, and a spinal can cause severe hypotension in these patients."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Induction In Shock","stem":"A 30-year-old man with a ruptured spleen reaches theatre at a district hospital. BP is 80/50 mmHg and HR 130/min despite fluids and blood. Which induction agent is the best choice?","options":["Thiopental 5 mg/kg","Ketamine in a reduced dose","Propofol 2.5 mg/kg","Midazolam 0.3 mg/kg"],"correct":1,"explanation":"Ketamine stimulates the sympathetic system and usually keeps the blood pressure up, so it is preferred in haemorrhagic shock; the dose is reduced because it can still depress a catecholamine-depleted heart. Full doses of propofol or thiopental cause vasodilation and myocardial depression and can cause severe hypotension or arrest in a shocked patient."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Fasting After Fatty Meals","stem":"Four adults are booked for elective surgery under general anaesthesia. Which of these intakes needs the longest fasting time before induction?","options":["A glass of cow's milk","A plate of fried meat and chips","A slice of dry toast","A cup of black coffee"],"correct":1,"explanation":"ASA guidance advises 8 hours or more after fried or fatty food, because fat slows gastric emptying. A light meal such as toast and non-human milk need 6 hours, and black coffee is a clear fluid (2 hours)."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Ketamine Contraindications","stem":"For which patient is ketamine the least suitable induction agent?","options":["A 32-year-old with severe pre-eclampsia, BP 176/114 mmHg","A 9-year-old with acute severe asthma needing surgery","A 25-year-old in hypovolaemic shock from a femur fracture","A 4-year-old needing a short burns dressing change"],"correct":0,"explanation":"Ketamine raises heart rate and blood pressure through sympathetic stimulation, so it can worsen severe hypertension and is avoided in severe pre-eclampsia. It is useful in asthma (bronchodilator), in hypovolaemia (supports blood pressure) and for short procedures such as burns dressings."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Chewing Gum Before Surgery","stem":"A healthy 30-year-old woman is waiting in theatre reception for elective laparoscopic cholecystectomy. She has fasted correctly but is chewing gum. What should the anaesthetist do?","options":["Remove the gum and postpone surgery for 2 hours","Proceed but change the plan to a rapid sequence induction","Ask her to remove the gum and proceed without delay","Postpone surgery for 6 hours because gum counts as food"],"correct":2,"explanation":"The 2023 ASA fasting update suggests not delaying surgery in healthy adults once the gum has been removed (it must be out before induction). Chewing gum does not meaningfully increase gastric volume, so treating it as food and postponing for 6 hours is not needed."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Ketamine Emergence Reactions","stem":"A 20-year-old is to have a short procedure under ketamine anaesthesia. Which measure best reduces the risk of bad dreams and agitation on waking?","options":["Give midazolam as part of the anaesthetic","Give atropine just before the ketamine","Give ondansetron at the end of the procedure","Use a larger ketamine dose so he sleeps longer"],"correct":0,"explanation":"Benzodiazepines such as midazolam reduce ketamine emergence reactions, as does a quiet recovery area. Atropine only reduces the extra salivation caused by ketamine and does not prevent emergence reactions; a larger ketamine dose does not help either."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Clear Carbohydrate Drinks","stem":"A healthy 45-year-old man is booked for elective knee surgery at 11:00. He had no solid food after midnight and drank 400 mL of a clear carbohydrate drink (no milk, no pulp) at 08:30. What is the best action?","options":["Delay surgery until 12:30, 4 hours after the drink","Cancel surgery and rebook him for another day","Delay surgery until 14:30, 6 hours after the drink","Proceed with surgery as planned at 11:00"],"correct":3,"explanation":"Healthy adults may drink carbohydrate-containing clear liquids until 2 hours before elective surgery. From 08:30 to 11:00 is 2.5 hours, so the fast is adequate; the 6-hour rule applies to light meals and milk, not to clear drinks."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Etomidate Adverse Effects","stem":"Etomidate is chosen for a septic patient because it keeps the blood pressure stable. Which side effect is a particular concern in this patient?","options":["Suppression of adrenal steroid production","Marked histamine release and bronchospasm","Triggering of malignant hyperthermia","A rise in intracranial pressure"],"correct":0,"explanation":"Etomidate inhibits 11-beta-hydroxylase and blocks cortisol synthesis for many hours even after a single dose, which is a concern in sepsis. It causes very little histamine release, lowers rather than raises intracranial pressure, and is not a malignant hyperthermia trigger."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"ASA Physical Status II","stem":"A 48-year-old teacher has hypertension that is well controlled on amlodipine. She has no other illness and no limitation of daily activities. She is booked for elective thyroidectomy. What is her ASA physical status?","options":["ASA I","ASA II","ASA IV","ASA III"],"correct":1,"explanation":"Well-controlled hypertension is a mild systemic disease without functional limitation, which is ASA II. ASA III needs severe systemic disease with substantial functional limitation, such as poorly controlled hypertension or diabetes."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Intra-arterial Thiopental","stem":"During induction with thiopental, the patient cries out with severe burning pain in the hand and the fingers turn pale. Intra-arterial injection is suspected. What should you do first?","options":["Give the rest of the dose slowly through it","Apply a tourniquet above the cannula site","Remove the cannula at once and press firmly","Stop injecting and leave the cannula in place"],"correct":3,"explanation":"Stop the injection but keep the cannula in the artery so that saline, a vasodilator (such as papaverine) and heparin can be given through it; a sympathetic block may follow. Removing the cannula loses this route, and a tourniquet worsens the ischaemia."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"ASA Physical Status IV","stem":"A 64-year-old man had a myocardial infarction 6 weeks ago and still gets chest pain when he walks slowly on level ground. He is now assessed for surgery. What is his ASA physical status?","options":["ASA IV","ASA II","ASA V","ASA III"],"correct":0,"explanation":"A myocardial infarction within the last 3 months with ongoing ischaemic chest pain is severe systemic disease that is a constant threat to life: ASA IV. ASA III fits an infarction more than 3 months ago without ongoing ischaemia, and ASA V is a moribund patient not expected to survive without the operation."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Porphyria And Induction","stem":"A 26-year-old woman with known acute intermittent porphyria needs a general anaesthetic for an appendicectomy. Which drug must be avoided?","options":["Thiopental","Propofol","Suxamethonium","Fentanyl"],"correct":0,"explanation":"Barbiturates such as thiopental induce ALA synthase and can precipitate an acute porphyric crisis. Propofol, fentanyl and suxamethonium are considered safe in porphyria."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Emergency ASA Modifier","stem":"A previously healthy 22-year-old student has acute appendicitis. He is haemodynamically stable and has no other medical problems. He is taken to theatre the same night. How should his ASA physical status be recorded?","options":["ASA I","ASA I E","ASA II E","ASA III E"],"correct":1,"explanation":"He has no systemic disease, so he is ASA I, and the letter E is added because a delay in treatment would increase the threat to his life. Writing ASA I alone hides the emergency nature of the case, which carries a higher risk than the same patient having elective surgery."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Propofol Injection Pain","stem":"A patient complains of severe arm pain as propofol is injected into a small vein on the back of the hand. Which measure best reduces this pain next time?","options":["Lidocaine IV first, and use a large forearm vein","Put ice on the arm before the injection","Slower injection into the same small hand vein","Dilute the propofol in 5% dextrose first"],"correct":0,"explanation":"Giving lidocaine before (or mixed with) propofol and using a large forearm or antecubital vein are the most effective ways to reduce propofol injection pain. Slow injection into a small vein does not help, and diluting propofol or cooling the arm is much less effective than lidocaine with a large vein."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"ASA Physical Status V","stem":"A 72-year-old man arrives at a referral hospital with a ruptured abdominal aortic aneurysm and a blood pressure of 70/40 mmHg. He is taken straight to theatre. What is his ASA physical status?","options":["ASA VI E","ASA V E","ASA IV E","ASA III E"],"correct":1,"explanation":"A moribund patient who is not expected to survive without the operation is ASA V; a ruptured aortic aneurysm is one of the ASA's own examples, and E marks the emergency. ASA VI is reserved for a brain-dead patient whose organs are being removed for donation."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Redistribution After Bolus","stem":"A healthy patient given a single induction dose of propofol wakes after about 5 to 10 minutes. What mainly explains this quick recovery?","options":["Rapid breakdown of the drug by the liver","Breakdown of the drug by plasma cholinesterase","Rapid excretion of unchanged drug in urine","Redistribution of the drug from brain to muscle and fat"],"correct":3,"explanation":"After a single bolus, the drug leaves the brain as it redistributes to muscle and fat; this, rather than metabolism, ends the clinical effect. Propofol does have high liver clearance, but metabolism matters more after repeated doses or infusions."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Functional Capacity Assessment","stem":"During preoperative assessment, which statement from a 60-year-old patient best shows a functional capacity of at least 4 METs?","options":["\"I walk one block slowly on flat ground.\"","\"I can wash the dishes and dust the furniture.\"","\"I climb two flights of stairs without stopping.\"","\"I can walk around inside my own house.\""],"correct":2,"explanation":"Climbing a flight of stairs or walking up a hill needs about 4 METs, so two flights without stopping shows adequate reserve. Walking indoors, light housework and slow walking on the flat all need less than 4 METs."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Potency And MAC","stem":"Which inhalational agent is the most potent, meaning it has the lowest MAC?","options":["Desflurane","Nitrous oxide","Halothane","Sevoflurane"],"correct":2,"explanation":"Potency is the inverse of MAC. Halothane has the lowest MAC (about 0.75%), lower than isoflurane, sevoflurane and desflurane; nitrous oxide has a MAC above 100%, so it cannot give full anaesthesia on its own at normal pressure."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Stopping Smoking Before Surgery","stem":"A 50-year-old heavy smoker is booked for elective hernia repair tomorrow. He asks whether stopping smoking tonight is worth it. What is the main benefit of stopping 12-24 hours before surgery?","options":["Better mucociliary clearance with less sputum","Lower carboxyhaemoglobin, so blood carries more oxygen","Lower risk of postoperative wound infection","Less airway reactivity and less bronchospasm"],"correct":1,"explanation":"Carbon monoxide has a short half-life, so 12-24 hours without smoking lowers carboxyhaemoglobin and improves oxygen delivery. Recovery of ciliary function, sputum, wound healing and airway reactivity takes weeks of abstinence, so these are not the short-term benefit."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Factors Lowering MAC","stem":"Which of these patient factors reduces the MAC of a volatile anaesthetic?","options":["Pregnancy","Hyperthyroidism","Chronic alcohol misuse","Fever of 39°C"],"correct":0,"explanation":"MAC falls in pregnancy, as it does with old age, hypothermia, and opioids or sedatives, so less volatile agent is needed. Chronic alcohol use and hyperthermia increase MAC, and thyroid disease does not change MAC."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Modified Mallampati Class","stem":"With the patient sitting, mouth fully open and tongue out, you can see the soft palate and only the base of the uvula. What is the modified Mallampati class?","options":["Class III","Class IV","Class II","Class I"],"correct":0,"explanation":"Class III shows the soft palate and the base of the uvula only. Class II also shows the whole uvula and fauces, Class I adds the tonsillar pillars, and in Class IV the soft palate is not seen at all."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Speed Of Induction","stem":"Induction with sevoflurane is faster than with isoflurane. Which property mainly explains this?","options":["A lower blood:gas partition coefficient","A lower saturated vapour pressure","A higher oil:gas partition coefficient","A higher MAC value"],"correct":0,"explanation":"A less blood-soluble agent (lower blood:gas coefficient) needs less drug to dissolve in blood before alveolar and brain partial pressures rise, so induction and recovery are faster. MAC and the oil:gas coefficient describe potency, not speed of onset."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Predicting Difficult Laryngoscopy","stem":"During airway assessment of a 40-year-old man, which single finding most suggests that direct laryngoscopy will be difficult?","options":["Mouth opening of 5 cm between the incisors","Full neck extension without pain","Modified Mallampati Class I view","Thyromental distance of 5 cm"],"correct":3,"explanation":"A thyromental distance under 6 cm means a small mandibular space, so the tongue cannot be moved out of the way and the larynx appears anterior. A mouth opening of 5 cm is normal (under 3 cm is concerning), and Mallampati I with full neck movement predicts easier laryngoscopy."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Gas Induction In Children","stem":"A 3-year-old needs an inhalational induction because no IV access is available. Which agent is unsuitable because it irritates the airway and causes coughing and laryngospasm?","options":["Halothane","Desflurane","Nitrous oxide in oxygen","Sevoflurane"],"correct":1,"explanation":"Desflurane is pungent and causes coughing, breath-holding and laryngospasm, so it is not used for gas induction. Sevoflurane (and halothane, where still used) is non-irritant and suitable for inhalational induction."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Post-Dural Puncture Headache","stem":"A 24-year-old woman had a caesarean section under spinal anaesthesia with a 22G Quincke needle. On day 2 she has a frontal and neck headache that is severe when she sits up and almost gone when she lies flat. Temperature 36.8°C, BP 118/72 mmHg, no neurological deficit. What is the most likely diagnosis?","options":["Bacterial meningitis","Cortical vein thrombosis","Post-dural puncture headache","Headache of pre-eclampsia"],"correct":2,"explanation":"A postural headache (worse upright, relieved lying flat) starting within a few days of dural puncture with a cutting needle is typical of PDPH caused by CSF leak. Meningitis gives fever and a headache that is not relieved by lying down, and pre-eclampsia headache usually comes with raised BP."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Starting Adult CPR","stem":"A 55-year-old man on the surgical ward suddenly collapses. He does not respond and is not breathing normally. You have shouted for help and a colleague is bringing the defibrillator. What should you do next?","options":["Feel for a carotid pulse for one full minute to be sure","Start chest compressions at 100-120 per minute, 5-6 cm deep","Give five rescue breaths before doing anything else","Turn him into the recovery position and wait for the team"],"correct":1,"explanation":"An unresponsive adult who is not breathing normally is in cardiac arrest until proven otherwise, so start CPR at once (30 compressions : 2 breaths, 100-120/min, 5-6 cm deep); any pulse check must take no more than 10 seconds. Five rescue breaths first is the sequence for children and drowning, not for a sudden adult collapse."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Epidural Blood Patch","stem":"On day 4 after an accidental dural puncture during a labour epidural, a mother still has a severe postural headache despite oral fluids, paracetamol and caffeine. She cannot sit up to breastfeed. What is the most effective treatment?","options":["Strict bed rest lying flat for 7 days","A repeat lumbar puncture to measure CSF pressure","Epidural injection of 20 mL bupivacaine 0.25%","Epidural blood patch with about 20 mL of her own blood"],"correct":3,"explanation":"For persistent, disabling PDPH an epidural blood patch (about 20 mL of sterile autologous blood injected into the epidural space at or below the puncture level) is the most effective treatment. Bed rest does not treat or prevent PDPH, and epidural local anaesthetic gives no lasting benefit."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Action After a Shock","stem":"During a cardiac arrest in the emergency department, the monitor shows ventricular fibrillation and one shock is given. What should the team do immediately after the shock is delivered?","options":["Look at the monitor to confirm the new rhythm","Resume chest compressions at once for 2 minutes","Charge the defibrillator and give a second shock","Check the carotid pulse for 10 seconds"],"correct":1,"explanation":"Chest compressions are restarted immediately after the shock, and the rhythm is checked again only after 2 minutes, because even if a rhythm returns the heart rarely pumps well straight away. Stopping to check the monitor or pulse lengthens the pause in compressions and lowers the chance of survival."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Spinal Needle Choice","stem":"You are choosing equipment for a spinal anaesthetic in a 26-year-old woman for elective caesarean section. Which choice most reduces her risk of post-dural puncture headache?","options":["Keeping her flat in bed for 24 hours after surgery","A 22G Quincke (cutting) spinal needle","A 25G pencil-point (e.g. Whitacre) spinal needle","Restricting oral fluids for 12 hours after surgery"],"correct":2,"explanation":"Small-gauge atraumatic (pencil-point) needles leave a smaller dural hole and greatly reduce PDPH, which is most common in young pregnant women. Lying flat after the spinal does not prevent PDPH, and a large cutting needle increases the risk."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Pulseless Electrical Activity","stem":"A monitored patient in the recovery room becomes unresponsive. The ECG shows an organised narrow-complex rhythm at 70 per minute, but there is no pulse. CPR is started. Which drug treatment is correct?","options":["Amiodarone 300 mg IV bolus, then repeat 150 mg after 5 minutes","Atropine 3 mg IV once, then adrenaline only if no response","A shock at maximum energy first, then adrenaline 1 mg IV","Adrenaline 1 mg IV as soon as possible, repeated every 3-5 minutes"],"correct":3,"explanation":"This is pulseless electrical activity, a non-shockable rhythm, so give adrenaline 1 mg IV as soon as access is available and every 3-5 minutes, and look for reversible causes (4 Hs and 4 Ts). Shocks and amiodarone are for VF/pulseless VT, and atropine is no longer used in PEA or asystole."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"High Spinal Block","stem":"Five minutes after a spinal anaesthetic for caesarean section, a woman says her hands feel weak and she is struggling to breathe. BP is 70/40 mmHg, HR 48/min, and she is becoming drowsy. What should you do first?","options":["Call for help, give 100% oxygen, support ventilation and treat BP with vasopressors","Give IV naloxone 400 micrograms to reverse the spinal block","Reassure her that a feeling of breathlessness is normal after a spinal","Sit her fully upright to stop the local anaesthetic spreading higher"],"correct":0,"explanation":"Arm weakness, breathing difficulty, hypotension, bradycardia and drowsiness mean a high spinal: manage ABC with oxygen, assisted ventilation or intubation if needed, vasopressors/atropine and left uterine displacement. Sitting her up worsens venous return and hypotension without reversing the block, and naloxone does not reverse local anaesthetic."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Refractory VF Antiarrhythmic","stem":"A 60-year-old man is still in ventricular fibrillation after three shocks with good-quality CPR. An IV line is in place. Which antiarrhythmic drug and dose should be given now?","options":["Adenosine 6 mg by rapid IV push","Magnesium sulfate 2 g IV as routine","Amiodarone 150 mg IV infused over 20 minutes","Amiodarone 300 mg IV bolus"],"correct":3,"explanation":"For VF/pulseless VT that persists after three shocks, amiodarone 300 mg IV bolus is given; a further 150 mg may follow after the fifth shock. The 150 mg dose is the second (or non-arrest) dose, adenosine is for regular narrow-complex tachycardia, and magnesium is only for torsades de pointes or low magnesium."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Spinal Bradycardia Mechanism","stem":"After a spinal anaesthetic the sensory block reaches T2, and the heart rate falls from 88 to 46/min. What is the main cause of this bradycardia?","options":["Direct vagal stimulation by the local anaesthetic","Block of the cardiac accelerator sympathetic fibres (T1–T4)","Block of the phrenic nerves (C3–C5)","Histamine release caused by bupivacaine"],"correct":1,"explanation":"A high block reaches the cardiac accelerator fibres (T1–T4), leaving vagal tone unopposed; reduced venous return adds to the slowing. Phrenic nerve block affects breathing, not heart rate, and bupivacaine does not cause histamine release."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Tension Pneumothorax in Arrest","stem":"Soon after a right subclavian central line is inserted, a ventilated ICU patient desaturates and the airway pressure rises. Breath sounds are absent on the right, the trachea is shifted to the left, and the patient then loses the pulse. What is the most important immediate action besides CPR?","options":["Perform pericardiocentesis for a likely cardiac tamponade","Send for an urgent chest X-ray to confirm the diagnosis","Decompress the right chest at once with a needle or open thoracostomy","Give amiodarone 300 mg IV for a likely arrhythmia"],"correct":2,"explanation":"One-sided absent breath sounds, rising airway pressure and tracheal shift after line insertion mean tension pneumothorax, a reversible cause of arrest that must be treated clinically without waiting for an X-ray. Tamponade gives raised JVP and quiet heart sounds but equal breath sounds and a central trachea."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Differential Neuraxial Block","stem":"A patient's spinal anaesthetic gives a sensory (pinprick) block up to T6. At about which level does the sympathetic block usually reach?","options":["T6","T4","T8","T10"],"correct":1,"explanation":"Thin sympathetic fibres are blocked most easily, so the sympathetic block is usually about 2 segments higher than the sensory block, and the motor block about 2 segments lower. So with sensory T6, sympathetic block reaches about T4, which explains hypotension that seems out of proportion to the sensory level."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric CPR Ratio","stem":"Two nurses are giving CPR to a 4-year-old child in cardiac arrest. No advanced airway is in place. What compression-to-ventilation ratio should they use?","options":["15 compressions to 2 breaths","3 compressions to 1 breath","30 compressions to 2 breaths","5 compressions to 1 breath"],"correct":0,"explanation":"For children beyond the newborn period, two healthcare rescuers use 15 compressions to 2 breaths, because cardiac arrest in children is usually caused by hypoxia, so ventilation matters more. 30:2 is the adult ratio (also used by a lone rescuer in AHA guidance), and 3:1 is the ratio for newborn resuscitation."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Epidural Test Dose","stem":"A labour epidural catheter is tested with 3 mL of lidocaine 2% with adrenaline 1:200,000, given between contractions. Within one minute her heart rate rises from 84 to 120/min and she feels palpitations. What is the most likely cause?","options":["The catheter is in the subarachnoid space","The catheter is correctly placed in the epidural space","She is anxious about the procedure","The catheter tip is inside an epidural vein"],"correct":3,"explanation":"The test dose contains 15 micrograms of adrenaline (3 mL × 5 micrograms/mL); a quick rise in HR of more than about 20/min within a minute suggests intravascular placement, so the catheter must be withdrawn or re-sited. An intrathecal catheter instead gives a rapid dense sensory and motor block within a few minutes."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Ventilation With Advanced Airway","stem":"During adult CPR a tracheal tube has been placed and its position confirmed with capnography. How should compressions and ventilations now be given?","options":["30 compressions, then a pause for 2 breaths","15 compressions, then a pause for 2 breaths","Continuous compressions with 20-25 breaths per minute","Continuous compressions with 10 breaths per minute"],"correct":3,"explanation":"Once an advanced airway is in place, compressions continue without pauses and the lungs are ventilated about 10 times per minute (one breath every 6 seconds). Faster ventilation raises chest pressure, reduces blood return to the heart and lowers CO2 too much."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Epidural Space Anatomy","stem":"During a midline approach to the lumbar epidural space, the loss of resistance is felt as the needle tip passes through which structure?","options":["Dura mater","Supraspinous ligament","Interspinous ligament","Ligamentum flavum"],"correct":3,"explanation":"The needle passes skin, subcutaneous tissue, supraspinous ligament, interspinous ligament and then the firm ligamentum flavum; leaving the ligamentum flavum gives the loss of resistance into the epidural space. Passing through the dura would give CSF (dural puncture)."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Cardiac Arrest in Pregnancy","stem":"A woman at 34 weeks of pregnancy collapses on the antenatal ward with no signs of life. CPR is started with her lying on her back on a firm surface. Which additional step will most improve the effectiveness of chest compressions?","options":["Turn her fully onto her right side","Manually push the uterus to the left side","Raise both legs to 45 degrees to increase venous return","Compress faster, at about 140 per minute"],"correct":1,"explanation":"From about 20 weeks the uterus compresses the inferior vena cava and aorta when the woman is supine, so manual left uterine displacement improves venous return while she stays flat for good compressions. A full lateral position makes effective compressions almost impossible, and the compression rate stays at 100-120/min."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Spinal Landmarks","stem":"You are about to perform a spinal anaesthetic in an adult. A line joining the tops of the iliac crests (Tuffier's line) usually crosses the spine at which level?","options":["L4 spinous process or L4–L5 interspace","L2 spinous process","T12 spinous process","S1 spinous process"],"correct":0,"explanation":"Tuffier's line usually crosses L4 or the L4–L5 interspace, which helps choose a space below the end of the spinal cord (L1–L2 in adults). Choosing L2 or higher risks needle injury to the conus."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Unstable Narrow-Complex Tachycardia","stem":"In the recovery room a 45-year-old woman develops a regular narrow-complex tachycardia at 190 per minute. Her BP is 70/40 mmHg, she has chest pain and she is confused. What is the most appropriate treatment?","options":["Synchronised DC cardioversion under sedation","Unsynchronised shock at maximum energy","Carotid sinus massage, then observe for 30 minutes","Verapamil 5 mg IV given slowly"],"correct":0,"explanation":"A tachycardia with adverse features (shock, chest pain, confusion) needs synchronised electrical cardioversion, with sedation or anaesthesia if she is conscious. Unsynchronised shocks are for pulseless VT/VF and can trigger VF if given in a perfusing rhythm, and verapamil can worsen the hypotension."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Epidural Haematoma","stem":"A 66-year-old man had a total knee replacement under combined spinal–epidural and is receiving enoxaparin. Ten hours after surgery he has new severe back pain and both legs are getting weaker, even though the epidural infusion was stopped 4 hours ago. What is the best action?","options":["Remove the catheter and review him the next morning","Urgent MRI of the spine and immediate neurosurgical referral","Give IV naloxone and observe for improvement","Reassure him that the epidural block is wearing off slowly"],"correct":1,"explanation":"Back pain with worsening leg weakness after the infusion has stopped is an epidural haematoma until proven otherwise; recovery is best if decompression is done within about 8 hours. A block that is wearing off gets better, not worse."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Classes of Haemorrhage","stem":"A 70 kg man is brought in after a stab wound to the abdomen. HR 125/min, BP 88/60 mmHg, he is anxious and confused, and urine output since catheter insertion is about 10 mL/hour. Using the ATLS classification, about how much of his blood volume has he lost?","options":["31-40%","More than 40%","15-30%","Less than 15%"],"correct":0,"explanation":"A falling systolic BP with marked tachycardia, confusion and urine output of 5-15 mL/h fits class III haemorrhage (31-40% of blood volume, about 1.5-2 L in a 70 kg adult). In class II (15-30%) the systolic BP is usually still normal; class IV (>40%) has very low BP, lethargy and almost no urine."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Neuraxial Block And LMWH","stem":"A woman on prophylactic enoxaparin 40 mg once daily had her last dose at 20:00. She is listed for elective surgery under spinal anaesthesia the next day. What is the earliest time the spinal can be safely performed?","options":["04:00 the next morning","08:00 the next morning","00:00 (midnight)","22:00 the same evening"],"correct":1,"explanation":"A neuraxial block should be done at least 12 hours after a prophylactic dose of LMWH (24 hours after a therapeutic dose): 20:00 + 12 hours = 08:00. Earlier times leave active anticoagulant and raise the risk of epidural haematoma."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Vasopressor in Septic Shock","stem":"A 50-year-old woman with peritonitis has a mean arterial pressure of 55 mmHg after 30 mL/kg of IV crystalloid. Her lactate is 5 mmol/L. Which vasopressor should be started first?","options":["Phenylephrine","Dopamine","Dobutamine","Noradrenaline (norepinephrine)"],"correct":3,"explanation":"In septic shock that stays hypotensive after initial fluids, noradrenaline is the first-line vasopressor, aiming for a MAP of at least 65 mmHg. Dopamine causes more arrhythmias, and dobutamine is an inotrope that can lower BP further through vasodilatation."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Spinal in Aortic Stenosis","stem":"A 75-year-old man with severe aortic stenosis (valve area 0.7 cm²) needs a transurethral resection of the prostate. Why is a single-shot spinal anaesthetic risky for him?","options":["Local anaesthetic is far more toxic to a stenotic heart","The spinal makes his heart rate rise sharply","The spinal causes a sharp rise in blood pressure that strains the valve","He cannot raise his cardiac output when vascular resistance falls suddenly"],"correct":3,"explanation":"In severe aortic stenosis the cardiac output is relatively fixed, so the sudden vasodilation of a single-shot spinal causes hypotension and poor coronary perfusion, which can spiral into ischaemia and cardiac arrest. A spinal lowers rather than raises blood pressure and tends to slow the heart, so a slowly titrated technique with vasopressors ready is preferred."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Neurogenic Shock","stem":"A young man has a cervical spine injury after a motorcycle crash. His BP is 80/45 mmHg, HR 50/min, and his hands and feet are warm and dry. There is no external bleeding. What type of shock is most likely?","options":["Neurogenic shock","Hypovolaemic shock","Septic shock","Cardiogenic shock"],"correct":0,"explanation":"Injury to the cervical or high thoracic cord removes sympathetic tone, giving vasodilatation (warm, dry skin) and unopposed vagal slowing of the heart (bradycardia) with hypotension. Hypovolaemic shock causes tachycardia and cold, clammy skin, although hidden bleeding must still be excluded in any trauma patient."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Baricity And Saddle Block","stem":"A 50-year-old man needs a haemorrhoidectomy under spinal anaesthesia. You want a block limited to the sacral segments (saddle block). What is the best technique?","options":["Inject a small dose of hyperbaric bupivacaine sitting, and keep him sitting for a few minutes","Inject isobaric bupivacaine lying on his side, then tilt him head-down","Inject hyperbaric bupivacaine sitting, then lay him flat and head-down at once","Inject a large volume of plain bupivacaine quickly with repeated barbotage"],"correct":0,"explanation":"Hyperbaric (heavy) solution sinks under gravity, so keeping the patient sitting for a few minutes keeps it around the sacral roots. Lying flat or head-down straight away lets the solution spread up to the thoracic segments."},
    ],
  },
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-anaesthesia-licensing-exam","name":"Anaesthesia Licensing Exam (RAHPC)"},
    slug: "rahpc-anaesthesia-mock-exam-2",
    title: "Anaesthesia Licensing Exam (RAHPC) — Mock Exam 2",
    summary: "Anaesthetic Pharmacology and General Anaesthesia; Regional Anaesthesia, Critical Care and Resuscitation.",
    free: false, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover anaesthesia practice."],
    sections: [{"name":"Anaesthetic Pharmacology and General Anaesthesia"},{"name":"Regional Anaesthesia, Critical Care and Resuscitation"}],
    questions: [
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Cormack-Lehane Grading","stem":"At direct laryngoscopy you can see the epiglottis but no part of the vocal cords or arytenoids. What is the Cormack-Lehane grade?","options":["Grade 2","Grade 3","Grade 4","Grade 1"],"correct":1,"explanation":"Grade 3 is epiglottis only. Grade 2 shows part of the glottis or only the arytenoids, Grade 1 shows most of the glottis, and in Grade 4 even the epiglottis is not seen."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Nitrous Oxide And Air Spaces","stem":"A 35-year-old with a chest injury and a small undrained pneumothorax needs an emergency laparotomy. Why should nitrous oxide be avoided?","options":["It causes severe bronchospasm in injured lungs","It diffuses into the air space and enlarges the pneumothorax","It strongly depresses the heart after trauma","It destroys surfactant and collapses the lung"],"correct":1,"explanation":"Nitrous oxide is about 30 times more soluble in blood than nitrogen, so it enters closed air spaces much faster than nitrogen can leave, expanding a pneumothorax and risking tension. It is not a bronchoconstrictor and has only mild direct myocardial depression."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Rheumatoid Arthritis Airway","stem":"A 58-year-old woman with long-standing rheumatoid arthritis is booked for knee replacement under general anaesthesia. Which airway problem is most important to assess before induction?","options":["Tracheal deviation caused by a large retrosternal goitre","Atlanto-axial instability with risk of cord injury on neck extension","Enlarged tongue causing upper airway obstruction after induction","Nasal polyps that would block a nasal tracheal tube"],"correct":1,"explanation":"Rheumatoid arthritis can weaken the transverse ligament, so neck extension during laryngoscopy may cause atlanto-axial subluxation and spinal cord injury; ask about neck symptoms and consider flexion-extension X-rays. Temporomandibular and cricoarytenoid joint disease also occur, but macroglossia and goitre are not features of rheumatoid arthritis."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Diffusion Hypoxia","stem":"At the end of an anaesthetic using 66% nitrous oxide, the patient's SpO2 falls to 90% while breathing room air just after extubation. What is the best way to prevent this?","options":["Give a further dose of neostigmine","Give 100% oxygen for the first few minutes of recovery","Keep nitrous oxide running until extubation","Give naloxone to reverse any opioid effect"],"correct":1,"explanation":"When nitrous oxide is stopped, large volumes leave the blood into the alveoli and dilute the oxygen (diffusion hypoxia). Giving 100% oxygen for several minutes after turning nitrous oxide off prevents this; naloxone does not treat this cause."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Preoxygenation Technique","stem":"Before a rapid sequence induction for an emergency laparotomy, which is the most effective way to preoxygenate the patient?","options":["Nasal cannula at 2 L/min while breathing quietly for 5 minutes","Loose Hudson mask at 6 L/min while breathing quietly for 3 minutes","Non-rebreather mask at 15 L/min for 1 minute before induction","Tight-fitting face mask, 100% oxygen, tidal breathing for 3 minutes"],"correct":3,"explanation":"A sealed face mask with high-flow 100% oxygen for about 3 minutes (or 8 deep breaths) washes nitrogen out of the lungs and fills the functional residual capacity with oxygen; aim for an end-tidal oxygen of 0.9 or more. Loose and low-flow masks entrain room air, and 1 minute on a non-rebreather mask is too short and leaks too much."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Volatiles And Adrenaline","stem":"During nasal surgery, the surgeon infiltrates a solution containing adrenaline and the patient develops ventricular ectopic beats. With which maintenance agent is this most likely?","options":["Sevoflurane","Halothane","Isoflurane","Desflurane"],"correct":1,"explanation":"Halothane sensitises the myocardium to catecholamines, so adrenaline infiltration can trigger ventricular arrhythmias and its dose must be limited. Isoflurane, sevoflurane and desflurane sensitise the heart much less."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Cricoid Pressure Force","stem":"During a rapid sequence induction, an assistant applies cricoid pressure. Once the patient has lost consciousness, about what force should be applied?","options":["30 N (about 3 kg)","10 N (about 1 kg)","60 N (about 6 kg)","100 N (about 10 kg)"],"correct":0,"explanation":"Cricoid pressure starts at about 10 N while the patient is awake (more is uncomfortable) and is increased to about 30 N once consciousness is lost, which is enough to compress the oesophagus. Much higher forces such as 60 N or more can distort the larynx and make laryngoscopy and ventilation harder, while 10 N alone is too little after induction."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Definition Of MAC","stem":"Which statement correctly defines MAC (minimum alveolar concentration)?","options":["Vaporiser setting that keeps 50% of patients asleep","Inspired level that causes loss of consciousness in 50%","Alveolar level that stops movement to incision in 50% of patients","Alveolar level that stops movement to incision in 95% of patients"],"correct":2,"explanation":"MAC is the steady-state alveolar concentration, at one atmosphere, that prevents movement in response to a surgical skin incision in 50% of patients. About 1.3 MAC is needed to prevent movement in 95%, and the dial setting of the vaporiser is not the alveolar concentration."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Rocuronium Dose for RSI","stem":"A 35-year-old woman needs a rapid sequence induction for emergency surgery, but suxamethonium cannot be used. Which rocuronium dose gives good intubating conditions within about 60 seconds?","options":["1.2 mg/kg","0.6 mg/kg","3 mg/kg","0.3 mg/kg"],"correct":0,"explanation":"For RSI, rocuronium is given at a high dose of about 1.2 mg/kg (range 0.9 to 1.2 mg/kg), which gives intubating conditions in about 60 seconds, close to suxamethonium. The standard 0.6 mg/kg dose takes about 90 to 120 seconds, too slow for RSI; note that the high dose also lasts much longer, which matters if intubation fails."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Opioid Respiratory Depression","stem":"Two hours after a laparotomy, a 60-year-old who received IV morphine is very drowsy, with RR 6/min, pinpoint pupils and SpO2 86%. You have opened the airway and given oxygen. Which drug should you give?","options":["Naloxone in small IV doses, titrated to breathing","Flumazenil 200 micrograms IV","Neostigmine with glycopyrrolate IV","Atropine 0.6 mg IV"],"correct":0,"explanation":"This is opioid-induced respiratory depression, treated with naloxone given in small increments until breathing improves, so that analgesia is not fully reversed. Flumazenil reverses benzodiazepines, not opioids."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Vomiting During RSI","stem":"At induction for an emergency laparotomy, before the muscle relaxant has taken effect, the patient starts actively vomiting. Cricoid pressure is being applied. What should be done?","options":["Increase cricoid pressure firmly to block the oesophagus","Release cricoid pressure, tilt head-down and suction the pharynx","Start bag-mask ventilation to push the vomit back down","Give a second full dose of muscle relaxant at once"],"correct":1,"explanation":"Cricoid pressure should be released during active vomiting because pressure on an actively vomiting oesophagus risks oesophageal rupture; head-down tilt (or turning to the side) and suction protect the lungs. Pressing harder does not stop active vomiting and adds this risk, and mask ventilation would push vomit into the lungs."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Naloxone Duration","stem":"A patient with morphine overdose wakes after IV naloxone. Forty minutes later he is drowsy again with RR 7/min. What is the most likely reason?","options":["Naloxone's effect wears off before morphine's","Naloxone itself causes delayed sedation","He has developed an allergy to naloxone","The naloxone caused acute opioid withdrawal"],"correct":0,"explanation":"Naloxone has a shorter duration of action than morphine, so respiratory depression can return; repeat doses or a naloxone infusion and close monitoring are needed. Naloxone has no sedative effect of its own, and withdrawal causes agitation, not drowsiness."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Cannot Intubate Cannot Oxygenate","stem":"After failed intubation and failed supraglottic airway insertion, face-mask ventilation by two people also fails. The patient is fully paralysed and SpO2 is 72% and falling. What is the next action?","options":["Insert a nasopharyngeal airway and keep mask ventilating","Declare CICO and perform emergency front-of-neck access","Give sugammadex and wait for breathing to return","Make one more attempt at direct laryngoscopy"],"correct":1,"explanation":"When intubation, supraglottic airway and face mask (Plans A-C) have failed and oxygenation cannot be maintained, DAS guidance is to declare 'cannot intubate, cannot oxygenate' and perform front-of-neck access (Plan D) without delay. More laryngoscopy wastes time and causes swelling, and waking the patient is only an option while oxygenation can be maintained."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Opioid Chest Wall Rigidity","stem":"Straight after a rapid IV bolus of a large dose of fentanyl, before any muscle relaxant, you cannot ventilate the patient by bag and mask and the chest feels stiff. What is the most likely cause?","options":["Malignant hyperthermia triggered by fentanyl","Anaphylaxis to fentanyl with bronchospasm","Opioid-induced chest wall muscle rigidity","Pneumothorax caused by mask ventilation"],"correct":2,"explanation":"Rapid large doses of potent opioids can cause truncal (chest wall) rigidity, which is treated with a neuromuscular blocker or naloxone. Opioids are not malignant hyperthermia triggers, and true fentanyl anaphylaxis is very rare."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Front-of-Neck Access Technique","stem":"Which technique do the Difficult Airway Society guidelines recommend for emergency front-of-neck access in an adult?","options":["Formal surgical tracheostomy between the second and third tracheal rings","Narrow cannula through the cricothyroid membrane with low-flow oxygen tubing","Scalpel through the cricothyroid membrane, bougie, then a size 6.0 cuffed tube","Retrograde wire passed through the cricothyroid membrane into the mouth"],"correct":2,"explanation":"DAS recommends the scalpel-bougie-tube technique: a transverse stab through the cricothyroid membrane, rotate the blade, slide a bougie into the trachea, railroad a 6.0 cuffed tube and confirm with capnography. Narrow cannulae often kink or misplace and cannot ventilate with low-pressure oxygen, and a formal tracheostomy takes too long in an emergency."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Pethidine In Renal Failure","stem":"A man with chronic kidney failure has had repeated doses of pethidine for 3 days after surgery. He becomes agitated and twitchy, then has a seizure. What is the most likely cause?","options":["Build-up of the metabolite norpethidine","Build-up of morphine-6-glucuronide","Opioid withdrawal after a missed dose","Low blood sugar caused by pethidine"],"correct":0,"explanation":"Norpethidine (normeperidine) is excreted by the kidneys and accumulates in renal failure; it stimulates the brain, causing tremor, myoclonus and seizures. Morphine-6-glucuronide is a morphine metabolite that causes prolonged sedation, not seizures."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Choosing Laryngeal Mask Airway","stem":"In which patient is a first-generation laryngeal mask airway the poorest choice, so that a cuffed tracheal tube should be used instead?","options":["A fasted 30-year-old having a 30-minute elective knee arthroscopy","A 50-year-old with bowel obstruction and repeated vomiting for laparotomy","A fasted 8-year-old boy having a circumcision as a day case","A fasted 40-year-old having excision of a lipoma on the arm"],"correct":1,"explanation":"Bowel obstruction means a full stomach and a high risk of aspiration, so the airway must be protected with a cuffed tracheal tube after a rapid sequence induction. Fasted patients having short peripheral procedures are suitable for a laryngeal mask."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Opioid Choice In Renal Failure","stem":"A 55-year-old on haemodialysis needs opioid analgesia during surgery. Which opioid is the most suitable?","options":["Morphine","Fentanyl","Pethidine","Codeine"],"correct":1,"explanation":"Fentanyl is broken down by the liver to inactive metabolites, so it is preferred in renal failure (still titrated carefully). Morphine's active metabolite morphine-6-glucuronide builds up and causes prolonged sedation and respiratory depression, and pethidine's metabolite causes seizures."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Awake Tracheal Intubation","stem":"A 52-year-old man with ankylosing spondylitis has a fixed, flexed neck and a mouth opening of 2 cm. He needs elective spinal surgery under general anaesthesia with a tracheal tube. What is the safest airway plan?","options":["Gas induction followed by a laryngeal mask airway","Awake fibreoptic intubation with topical anaesthesia","Rapid sequence induction and direct laryngoscopy","IV induction followed by blind nasal intubation"],"correct":1,"explanation":"When both laryngoscopy and rescue are expected to be difficult, securing the airway while the patient is awake and breathing keeps him safe if the attempt fails. Paralysing him first removes his own airway and could lead to a 'cannot intubate, cannot oxygenate' emergency."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Remifentanil Pharmacokinetics","stem":"After a 6-hour remifentanil infusion is stopped, the patient breathes and wakes within minutes. Why?","options":["It is quickly removed unchanged by the kidneys","It redistributes from the brain into fat stores","It is broken down by non-specific esterases in blood and tissue","It is broken down only by plasma cholinesterase"],"correct":2,"explanation":"Remifentanil has an ester link broken by non-specific blood and tissue esterases, so its context-sensitive half-time stays about 3 to 4 minutes whatever the infusion length (so longer-acting analgesia must be planned before it is stopped). It is not a substrate for plasma cholinesterase, so its action is not prolonged in suxamethonium apnoea."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Positioning for Laryngoscopy","stem":"Which head and neck position best lines up the airway for direct laryngoscopy in an adult of normal build?","options":["Neck fully flexed so that the chin touches the chest","Lower neck flexed on a pillow, head extended at the atlanto-occipital joint","Neck fully extended with a roll placed under the shoulders","Head flat on the table in a neutral position without a pillow"],"correct":1,"explanation":"The 'sniffing' position (lower neck flexion on a pillow plus extension at the atlanto-occipital joint) brings the oral, pharyngeal and laryngeal axes closer into line. A shoulder roll with neck extension is used in infants, whose large occiput already flexes the neck."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Intrathecal Morphine Monitoring","stem":"A woman had a caesarean section under spinal anaesthesia with intrathecal morphine. What is the most important ward monitoring after she leaves recovery?","options":["Blood pressure and pulse; breathing is not affected","Pain scores only, because the dose is very small","Respiratory rate and sedation checks for 12 to 24 hours","Respiratory rate checks for the first 2 hours only"],"correct":2,"explanation":"Water-soluble intrathecal morphine spreads slowly up to the brainstem, so respiratory depression can be delayed for many hours (often 6 to 12 hours). ASA guidance advises monitoring breathing and sedation for at least 24 hours (the SOAP obstetric consensus allows about 12 hours for healthy women given 150 micrograms or less); checking only in the first 2 hours would miss this late risk."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Pin Index Safety System","stem":"What is the purpose of the pin index safety system on anaesthetic gas cylinders?","options":["To reduce cylinder pressure to a safe working level","To stop a cylinder being fitted to the wrong gas yoke","To prevent the cylinder valve from opening too fast","To show how much gas remains in the cylinder"],"correct":1,"explanation":"Each gas has its own pattern of pins on the yoke that matches holes on the cylinder valve, so, for example, a nitrous oxide cylinder cannot be fitted to the oxygen yoke. Pressure is reduced by the regulator, and contents are shown by the gauge (or by weight for nitrous oxide)."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Tramadol And Seizures","stem":"A 40-year-old with poorly controlled epilepsy needs post-operative analgesia. Which drug is best avoided?","options":["Tramadol","Fentanyl","Paracetamol","Morphine"],"correct":0,"explanation":"Tramadol lowers the seizure threshold (and has serotonergic effects), so it is avoided in poorly controlled epilepsy. Paracetamol and standard opioids such as morphine and fentanyl do not lower the seizure threshold at normal doses."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Hypoxic Mixture Prevention","stem":"On a modern anaesthetic machine, the oxygen and nitrous oxide flow controls are linked mechanically or electronically. What is the main purpose of this link?","options":["To prevent delivery of a gas mixture too low in oxygen","To keep the total fresh gas flow at a constant level","To sound an alarm when the oxygen cylinder is empty","To switch off the vaporizer when nitrous oxide is off"],"correct":0,"explanation":"The proportioning system (for example Link-25) stops the user setting a nitrous oxide flow that would give less than about 25% oxygen. It does not protect against a wrong gas in the oxygen pipeline, so an oxygen analyser is still essential."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Fluid Choice in Head Injury","stem":"A 30-year-old with a severe head injury (GCS 8) has been intubated and needs IV fluid. Which IV fluid should be avoided?","options":["5% dextrose in water","Red cells if he is bleeding and anaemic","3% hypertonic saline when ICP is raised","0.9% sodium chloride"],"correct":0,"explanation":"Once its glucose is used, 5% dextrose becomes free water, which lowers plasma osmolality and worsens cerebral oedema; the hyperglycaemia it can cause also worsens brain injury. Isotonic 0.9% saline is the usual fluid, and hypertonic saline is given deliberately to reduce raised intracranial pressure."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Neuraxial Contraindications","stem":"Which of the following is an absolute contraindication to spinal anaesthesia?","options":["Taking aspirin 75 mg daily","The patient refuses after a full explanation","Previous lumbar spine surgery","Platelet count of 120 × 10^9/L"],"correct":1,"explanation":"Patient refusal is an absolute contraindication (as is infection at the puncture site). Aspirin alone does not prevent a spinal, and previous spine surgery is only a relative contraindication."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric Maintenance Fluid Type","stem":"A 6-year-old needs IV maintenance fluid for 24 hours after an appendicectomy. Which fluid is most appropriate?","options":["0.9% sodium chloride with 5% glucose","0.18% sodium chloride with 4% glucose","0.45% sodium chloride alone","5% glucose alone"],"correct":0,"explanation":"After surgery, stress raises ADH so children retain free water, and hypotonic fluids such as 0.18% saline with 4% glucose or 5% glucose can then cause dangerous hyponatraemia and brain swelling. NICE and AAP guidance recommend isotonic fluids (sodium 131-154 mmol/L) with glucose for maintenance, with electrolytes checked at least daily."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Transient Neurological Symptoms","stem":"A 35-year-old man had surgery in the lithotomy position under a lidocaine spinal. The next day he has aching pain in both buttocks spreading to the thighs. Power, sensation, and bladder and bowel function are normal. What is the most likely diagnosis?","options":["Cauda equina syndrome","Epidural haematoma","Transient neurological symptoms","Epidural abscess"],"correct":2,"explanation":"Buttock and leg pain without neurological deficit after a lidocaine spinal, especially in lithotomy, is typical of transient neurological symptoms, which settle within days with NSAIDs. Cauda equina syndrome causes saddle numbness and bladder or bowel dysfunction."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Burns Fluid Calculation","stem":"A 60 kg man with 30% total body surface area burns arrives 2 hours after the injury and has had no IV fluid yet. Using the Parkland formula (4 mL x weight in kg x %TBSA over the first 24 hours), at what rate should Ringer's lactate run for the rest of the first 8 hours?","options":["300 mL/hour","600 mL/hour","450 mL/hour","900 mL/hour"],"correct":1,"explanation":"Total = 4 x 60 x 30 = 7200 mL; half (3600 mL) is due in the first 8 hours counted from the time of the burn, and 6 of those hours remain, so 3600 / 6 = 600 mL/h, then adjusted to urine output. 450 mL/h (3600 / 8) forgets that 2 hours have already passed. (Current ATLS and American Burn Association guidance start lower, at 2 mL/kg/%TBSA, but this question asks for the classic Parkland figure given in the stem.)"},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Spinal Hypotension At Caesarean","stem":"A healthy woman has a spinal for elective caesarean section. Her baseline BP was 120/75 mmHg. Three minutes after the spinal, BP is 85/50 mmHg and HR 96/min. She has left uterine displacement and IV fluid is running. What is the best drug to give?","options":["IV atropine 0.6 mg","IV phenylephrine 50–100 micrograms","IV adrenaline 1 mg","IV ephedrine 30 mg as a single bolus"],"correct":1,"explanation":"Phenylephrine is the first-line vasopressor for spinal hypotension at caesarean section when HR is normal or high; aim to keep systolic BP at or above 90% of baseline. Large doses of ephedrine cross the placenta and cause fetal acidosis, and 1 mg adrenaline is a cardiac arrest dose."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Response to Fluid Bolus","stem":"A 70 kg man with a pelvic fracture receives a 1 litre crystalloid bolus. His BP rises from 85/50 to 110/70 mmHg, but 20 minutes later it falls back to 88/55 mmHg and his heart rate rises again. What does this response mean?","options":["He has been over-transfused and needs a diuretic","He has neurogenic shock and needs a vasopressor","He is still bleeding and needs blood and urgent bleeding control","He is a rapid responder and needs no further treatment"],"correct":2,"explanation":"This is a transient response: the circulation improves with fluid and then worsens again, showing ongoing bleeding that needs blood products and early surgical or radiological control. A rapid responder stays stable after the bolus, and repeated crystalloid alone in a bleeding patient worsens dilution and clotting."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Hypotension With Bradycardia","stem":"During caesarean section under spinal anaesthesia, BP falls to 82/48 mmHg and heart rate is 50/min. Which drug is the best choice?","options":["IV oxytocin 5 IU bolus","IV phenylephrine 100 micrograms, repeated","IV labetalol 10 mg","IV ephedrine 6–10 mg, repeated as needed"],"correct":3,"explanation":"When hypotension comes with bradycardia, ephedrine (alpha and beta effects) or an anticholinergic is preferred. Phenylephrine causes reflex slowing of the heart and would make the bradycardia worse."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Anaphylaxis Under Anaesthesia","stem":"Minutes after an IV antibiotic is given at induction, a 70 kg adult develops flushing, wheeze and a BP of 60/30 mmHg. The drug is stopped and help is called. Which drug treatment comes first?","options":["Chlorphenamine 10 mg IV","Adrenaline 50 micrograms IV, repeated as needed","Adrenaline 1 mg IV bolus","Hydrocortisone 200 mg IV"],"correct":1,"explanation":"Adrenaline is the key drug in anaphylaxis; in a monitored adult under anaesthesia it is given IV in small boluses of about 50 micrograms, titrated to response (IM 0.5 mg if there is no IV access). A 1 mg IV bolus is the cardiac arrest dose and can cause severe hypertension and arrhythmias, while steroids and antihistamines are only second-line."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Physiology Of Pregnancy","stem":"Why does a pregnant woman at term desaturate much faster than a non-pregnant woman during apnoea at induction of general anaesthesia?","options":["Her tidal volume and minute ventilation are reduced","Her functional residual capacity is reduced and her oxygen consumption is increased","Her haemoglobin is higher, so oxygen is released less easily","Her airway is narrower, so pre-oxygenation cannot work"],"correct":1,"explanation":"The gravid uterus pushes the diaphragm up, reducing FRC (the oxygen store), while oxygen consumption rises, so the store is used up quickly. Minute ventilation actually increases in pregnancy, and haemoglobin falls (dilutional anaemia)."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Bedside Blood Check","stem":"A unit of red cells arrives in theatre for a patient under general anaesthesia. Which check best prevents an ABO-incompatible transfusion?","options":["Matching the patient's wristband identity with the blood unit label at the bedside","Asking the blood bank by telephone to confirm the crossmatch","Checking the expiry date and colour of the blood unit","Giving the first 20 mL slowly and watching for a reaction"],"correct":0,"explanation":"Most ABO-incompatible transfusions come from identification errors, so the final bedside check of the patient's identity (name, hospital number, date of birth on the wristband) against the unit and compatibility label is the key safety step. Watching for a reaction is not protective under anaesthesia because the early symptoms are hidden."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Placental Transfer of Drugs","stem":"A woman has a caesarean section under general anaesthesia. Which drug given at induction crosses the placenta to the baby the least?","options":["Fentanyl","Ketamine","Rocuronium","Propofol"],"correct":2,"explanation":"Neuromuscular blockers such as rocuronium (and suxamethonium) are highly ionised and poorly lipid-soluble, so very little crosses the placenta and the baby is not paralysed. Propofol, ketamine and fentanyl are lipid-soluble and cross readily, which is why the baby may be sleepy if delivery is delayed after induction."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Haemolytic Reaction Under Anaesthesia","stem":"Ten minutes after a red-cell transfusion is started during general anaesthesia, the patient becomes hypotensive and tachycardic, the wound starts to ooze, and the urine in the catheter bag turns dark red. What should be done first?","options":["Slow the transfusion and give IV chlorphenamine","Run the rest of the unit quickly to correct the hypotension","Stop the transfusion and keep the vein open with saline through a new giving set","Give IV furosemide and continue the transfusion slowly"],"correct":2,"explanation":"Hypotension, unexplained bleeding (DIC) and haemoglobinuria under anaesthesia suggest an acute haemolytic reaction, so the transfusion must be stopped at once, the line kept open with saline, and the unit and patient identity rechecked. Slowing the rate and giving an antihistamine is for a mild allergic reaction and lets more incompatible blood in."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Obstetric Failed Intubation","stem":"During rapid sequence induction for an emergency caesarean section, you fail to intubate after two attempts. SpO2 is 93% and falling slowly. According to OAA/DAS guidance, what should you do next?","options":["Let the surgeon start while you continue trying to intubate","Stop laryngoscopy, insert a second-generation supraglottic airway and oxygenate","Give more suxamethonium and keep trying until the tube passes","Try blind nasal intubation to protect the airway quickly"],"correct":1,"explanation":"OAA/DAS guidance limits laryngoscopy to two attempts (a third only by an experienced colleague); then insert a supraglottic airway, preferably second-generation, because oxygenation comes first. Repeated attempts cause swelling and bleeding and lead to a can't-intubate, can't-oxygenate situation."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Restrictive Transfusion Threshold","stem":"A 58-year-old woman in ICU with sepsis is now stable, is not bleeding and has no heart disease. Her haemoglobin is 7.8 g/dL. What is the most appropriate transfusion plan?","options":["Give 2 units now, as she is in ICU","Transfuse now to keep haemoglobin above 10 g/dL","Do not transfuse unless haemoglobin falls below 7 g/dL","Transfuse whenever haemoglobin is below 9 g/dL"],"correct":2,"explanation":"For stable adult ICU patients without active bleeding or acute cardiac ischaemia, a restrictive threshold of 7 g/dL is recommended: it is as safe as a liberal strategy and avoids transfusion risks and wasted blood. Keeping haemoglobin above 9-10 g/dL gives no survival benefit in this group."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Block Height For Caesarean","stem":"Before the surgeon starts a caesarean section under spinal anaesthesia, which minimum block height to cold sensation (on both sides) is generally accepted as adequate?","options":["L1 (groin)","T4 (nipple line)","T10 (umbilicus)","T8"],"correct":1,"explanation":"Handling the peritoneum and uterus needs a block to about T4 to cold, tested on both sides before incision. A T10 block is enough for labour analgesia but will give pain during caesarean section."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Massive Transfusion Complications","stem":"During a trauma laparotomy, 8 units of red cells are given rapidly. The BP stays low despite good volume replacement, and the ECG now shows a prolonged QT interval. Which complication is most likely?","options":["Low ionised calcium caused by citrate","Hyperkalaemia from stored red cells","Delayed haemolytic transfusion reaction","Air embolism from the pressure bag"],"correct":0,"explanation":"Citrate in stored blood binds calcium, and with rapid transfusion the low ionised calcium causes hypotension, poor heart contraction and a prolonged QT; treat with IV calcium. Hyperkalaemia gives peaked T waves rather than a long QT, and a delayed haemolytic reaction appears days later."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Magnesium Toxicity","stem":"A woman with severe pre-eclampsia is on a magnesium sulphate infusion. Her respiratory rate is now 8/min and her knee reflexes are absent. What should you do first?","options":["Give IV diazepam to prevent a seizure","Stop the magnesium and give 10 mL of 10% calcium gluconate IV slowly","Give IV naloxone 400 micrograms to reverse respiratory depression","Give IV furosemide to increase magnesium excretion"],"correct":1,"explanation":"Loss of reflexes and slow breathing are signs of magnesium toxicity: stop the infusion, support breathing and give calcium gluconate 10% 10 mL IV slowly as the antidote. Naloxone has no effect on magnesium, and diazepam would deepen respiratory depression."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Platelet Storage","stem":"The theatre receives platelet concentrates for a bleeding patient, but the operation is delayed. How should platelets be stored until use?","options":["In a blood warmer at 37 °C","Frozen at -25 °C or colder","In the blood fridge at 2-6 °C","At 20-24 °C with gentle continuous agitation"],"correct":3,"explanation":"Platelets are kept at room temperature (20-24 °C) with gentle agitation; cold storage damages them and shortens their survival after transfusion. The 2-6 °C fridge is for red cells, and freezing is for plasma."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Magnesium And Muscle Relaxants","stem":"A woman on magnesium sulphate for pre-eclampsia needs general anaesthesia for caesarean section. How does magnesium affect a non-depolarising muscle relaxant such as rocuronium?","options":["It shortens its action, so a larger dose is needed","It reverses the block, so neostigmine is not needed","It has no effect on neuromuscular block","It prolongs and deepens the block, so use smaller doses and monitor"],"correct":3,"explanation":"Magnesium reduces acetylcholine release at the neuromuscular junction, so it potentiates non-depolarising relaxants; reduce doses and use a nerve stimulator. Giving a larger dose would cause prolonged weakness after surgery."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Transfusion Time Limit","stem":"A unit of red cells was taken out of the blood bank refrigerator at 08:00 and the transfusion was started straight away. By what time must the transfusion be completed?","options":["10:00","08:30","12:00","20:00"],"correct":2,"explanation":"WHO advises that a red-cell transfusion should be completed within 4 hours of the unit leaving the refrigerator, because bacteria can grow at room temperature: 08:00 + 4 h = 12:00. The 30-minute limit (08:30) is the time within which the transfusion should be started, not finished."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Pre-eclampsia General Anaesthesia","stem":"A woman with severe pre-eclampsia (BP 170/110 mmHg despite treatment) needs general anaesthesia for caesarean section. What is the main reason to give a short-acting opioid (e.g. alfentanil or remifentanil) or labetalol at induction?","options":["To prolong the action of suxamethonium","To reduce the risk of awareness","To blunt the hypertensive surge at laryngoscopy that can cause brain haemorrhage","To prevent uterine atony after delivery"],"correct":2,"explanation":"Laryngoscopy causes a sharp rise in BP, and in pre-eclampsia this can cause intracerebral haemorrhage, a leading cause of maternal death; a short-acting opioid or labetalol blunts this pressor response. Preventing awareness is the job of an adequate induction dose and volatile agent, not the main reason for these drugs; tell the neonatal team if an opioid was given."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"TACO Versus TRALI","stem":"A 78-year-old woman with heart failure is given 3 units of red cells quickly after a hip operation. Two hours later she is breathless, BP 170/95 mmHg, her JVP is raised and there are crackles at both lung bases. What is the most likely diagnosis?","options":["Transfusion-related acute lung injury (TRALI)","Acute haemolytic transfusion reaction","Transfusion-associated circulatory overload (TACO)","Anaphylactic transfusion reaction"],"correct":2,"explanation":"Fast transfusion in an elderly patient with heart failure, followed by hypertension, raised JVP and crackles, is circulatory overload (TACO), which responds to stopping the transfusion and giving a diuretic. TRALI usually causes hypotension and fever with a normal JVP, as the lung injury is not due to fluid overload."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Uterotonics In Asthma","stem":"After delivery under spinal anaesthesia, a woman with severe asthma has a postpartum haemorrhage from uterine atony. Oxytocin has been given. Which uterotonic should be AVOIDED in her?","options":["Ergometrine (her BP is normal)","Repeat oxytocin infusion","Misoprostol","Carboprost (15-methyl prostaglandin F2-alpha)"],"correct":3,"explanation":"Carboprost can cause severe bronchospasm and should be avoided in asthma. Ergometrine is avoided in hypertension or pre-eclampsia, but her BP is normal."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Tranexamic Acid in Trauma","stem":"A 30-year-old man with major bleeding after a road traffic crash reaches the district hospital 1 hour after the injury. What is the correct tranexamic acid regimen?","options":["Give 1 g IV over 10 minutes only after 3 hours from injury","Wait for clotting results and give it only if the INR is raised","Give 1 g orally every 8 hours for 3 days","Give 1 g IV over 10 minutes, then 1 g IV over 8 hours"],"correct":3,"explanation":"In bleeding trauma patients, tranexamic acid 1 g IV over 10 minutes followed by 1 g infused over 8 hours reduces death from bleeding when started within 3 hours of injury (CRASH-2). Starting it after 3 hours gave no benefit and was linked to more deaths from bleeding, so it should not be delayed for clotting tests."},
    ],
  },
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-anaesthesia-licensing-exam","name":"Anaesthesia Licensing Exam (RAHPC)"},
    slug: "rahpc-anaesthesia-mock-exam-3",
    title: "Anaesthesia Licensing Exam (RAHPC) — Mock Exam 3",
    summary: "Anaesthetic Pharmacology and General Anaesthesia; Regional Anaesthesia, Critical Care and Resuscitation.",
    free: false, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover anaesthesia practice."],
    sections: [{"name":"Anaesthetic Pharmacology and General Anaesthesia"},{"name":"Regional Anaesthesia, Critical Care and Resuscitation"}],
    questions: [
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Suxamethonium In Burns","stem":"A 28-year-old man who had 40% burns three weeks ago comes for skin grafting. Which drug should be avoided?","options":["Rocuronium","Suxamethonium","Fentanyl","Ketamine"],"correct":1,"explanation":"After a burn, extra-junctional acetylcholine receptors multiply (from about 24 hours until healing), and suxamethonium can then cause a dangerous rise in potassium and cardiac arrest. Non-depolarising relaxants such as rocuronium are safe, though larger doses may be needed."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Oxygen Pipeline Failure","stem":"During a laparotomy at a district hospital, the oxygen supply failure alarm sounds and the oxygen pipeline gauge reads zero. What should the anaesthetist do first?","options":["Switch off the ventilator and wait for the pipeline supply to return","Open the reserve oxygen cylinder on the machine and check the oxygen analyser","Turn up the nitrous oxide flow to keep the fresh gas flow the same","Turn up the volatile agent to make sure the patient stays asleep"],"correct":1,"explanation":"Opening the machine's reserve oxygen cylinder restores the oxygen supply at once; confirm it with the oxygen analyser, and if it fails, ventilate with a self-inflating bag on room air. Turning up nitrous oxide would give a hypoxic mixture, which is exactly what the failure alarm is there to prevent."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Suxamethonium Apnoea","stem":"Thirty minutes after a short procedure using suxamethonium, the patient is still not breathing and a nerve stimulator shows weak twitches. Plasma cholinesterase deficiency is suspected. What is the best management?","options":["Give naloxone and wait for breathing to return","Extubate and give oxygen by face mask","Give neostigmine to speed up the recovery","Keep him sedated and ventilated until full recovery"],"correct":3,"explanation":"Suxamethonium apnoea is managed by keeping the patient sedated and ventilated until the block wears off, then testing the patient and family. Neostigmine also inhibits plasma cholinesterase and can prolong or unpredictably change the block."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Backup Ventilation Equipment","stem":"As part of the machine check before a theatre list, which item must be immediately available in case the anaesthetic machine or oxygen supply fails?","options":["A spare bottle of volatile agent","A spare soda lime canister","A second laryngoscope handle","A self-inflating bag with a face mask"],"correct":3,"explanation":"Equipment-checking guidelines require an alternative means of ventilation, such as a self-inflating bag, that works without the machine or a gas supply. A spare laryngoscope is good practice but does not let you ventilate the patient if the machine fails."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Antimuscarinic With Neostigmine","stem":"Why is glycopyrrolate or atropine given together with neostigmine when reversing a neuromuscular block?","options":["To make the neostigmine act for longer","To prevent post-operative nausea and vomiting","To block muscarinic effects such as bradycardia","To strengthen the reversal of the muscle block"],"correct":2,"explanation":"Neostigmine increases acetylcholine at muscarinic as well as nicotinic receptors, causing bradycardia, bronchospasm, salivation and gut overactivity; the antimuscarinic blocks these effects. It adds nothing to the reversal at the neuromuscular junction."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Oxygen Flush Hazards","stem":"During maintenance with sevoflurane through a circle system, a trainee keeps pressing the oxygen flush button to refill the reservoir bag. Which risk is most important?","options":["Overdose, because flush gas passes the vaporizer","Hypoxia, because flush gas contains no oxygen","Awareness from diluted anaesthetic, and barotrauma","Hypercapnia from exhaustion of the soda lime"],"correct":2,"explanation":"The flush delivers pure oxygen at very high flow and bypasses the flowmeters and vaporizer, so it dilutes the volatile agent (risk of awareness) and can cause barotrauma if pressed during inspiration. Because it bypasses the vaporizer, it cannot cause an overdose."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Reversal Of Deep Block","stem":"At the end of a laparotomy with rocuronium, the train-of-four count is 0. Sugammadex is not available. What should you do?","options":["Keep ventilating and anaesthetised until twitches return, then reverse","Extubate deep and support breathing with a face mask","Give neostigmine now and extubate when breathing starts","Give a double dose of neostigmine to overcome the block"],"correct":0,"explanation":"Neostigmine only works once some recovery has started; with no twitches it is ineffective, and its ceiling effect means higher doses do not help. Keep the patient anaesthetised and ventilated until at least 2 (ideally 4) twitches return, then give neostigmine with an antimuscarinic."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Vaporizer Interlock System","stem":"Two vaporizers (isoflurane and sevoflurane) are mounted side by side on the machine. What is the purpose of the interlock system between them?","options":["To keep the output steady when the room becomes warm","To switch on the scavenging system automatically","To stop the vaporizers being filled with the wrong agent","To allow only one vaporizer to be turned on at a time"],"correct":3,"explanation":"The interlock stops two vaporizers being on together, which would deliver a mixture and possible overdose of volatile agents. Wrong-agent filling is prevented by agent-specific keyed fillers, and temperature compensation is a separate feature inside each vaporizer."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Sugammadex","stem":"Sugammadex rapidly reverses which neuromuscular blocking drug?","options":["Suxamethonium","Rocuronium","Cisatracurium","Atracurium"],"correct":1,"explanation":"Sugammadex is a cyclodextrin that encapsulates steroidal relaxants, most strongly rocuronium (and also vecuronium). It has no effect on benzylisoquinolinium drugs such as atracurium and cisatracurium, or on suxamethonium."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"WHO Checklist Sign In","stem":"Using the WHO Surgical Safety Checklist, which item is confirmed at Sign In, before induction of anaesthesia?","options":["The pulse oximeter is on the patient and working","Specimens are labelled with the patient's name","The surgeon reviews the expected critical steps","Instrument, sponge and needle counts are correct"],"correct":0,"explanation":"Sign In covers identity, site, procedure and consent, site marking, the anaesthesia machine and medication check, a working pulse oximeter, allergies, airway or aspiration risk and expected blood loss. Counts and specimen labelling are Sign Out items, and the surgeon's critical steps are reviewed at Time Out."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Relaxant In Organ Failure","stem":"A 50-year-old with both liver cirrhosis and kidney failure needs a muscle relaxant for a laparotomy. Which is the best choice?","options":["Vecuronium","Pancuronium","Cisatracurium","Rocuronium"],"correct":2,"explanation":"Cisatracurium (like atracurium) is broken down by Hofmann elimination, which does not depend on liver or kidney function. Rocuronium and vecuronium depend mainly on the liver and pancuronium on the kidney, so their effect is prolonged in organ failure."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Expected Blood Loss Threshold","stem":"At Sign In for a 20-kg child, the team discusses the risk of major blood loss. Using the WHO Surgical Safety Checklist threshold, above what blood loss should the team prepare IV access and blood?","options":["500 mL","140 mL","200 mL","70 mL"],"correct":1,"explanation":"The checklist asks about a risk of more than 500 mL blood loss in adults, or 7 mL/kg in children: 7 mL/kg x 20 kg = 140 mL. The adult figure of 500 mL is far too high for a small child."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Residual Neuromuscular Block","stem":"Which finding best confirms adequate recovery from a non-depolarising muscle relaxant before extubation?","options":["The patient opens the eyes when spoken to","Tidal volume of 5 mL/kg on the ventilator","Four visible twitches on a train-of-four","Train-of-four ratio of 0.9 or more on a quantitative monitor"],"correct":3,"explanation":"A measured train-of-four ratio of 0.9 or more is the accepted standard for adequate recovery. Four twitches can be present with a ratio as low as about 0.4, because fade is hard to see or feel above that level, and tidal volume or eye opening can return with significant residual block."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Diathermy Plate Placement","stem":"Where should the return electrode (patient plate) for monopolar diathermy be placed to lower the risk of burns?","options":["Over a bony prominence such as the sacrum or the hip bone","Over a metal hip prosthesis close to the surgical incision","On clean, dry skin over a large muscle near the operation site","On skin left wet with antiseptic to give better contact"],"correct":2,"explanation":"A large, well-perfused muscle area close to the site spreads the current over a wide area so heat does not build up. Bony prominences and metal implants give poor or uneven contact, and pooled antiseptic can cause burns or fire."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Suxamethonium Bradycardia","stem":"A 4-year-old receives a second dose of suxamethonium a few minutes after the first and develops severe bradycardia. What is the mechanism?","options":["Stimulation of cardiac muscarinic receptors","Blockade of cardiac nicotinic receptors","Severe hyperkalaemia from muscle damage","Release of histamine from mast cells"],"correct":0,"explanation":"Suxamethonium is like two joined acetylcholine molecules and stimulates cardiac muscarinic receptors, causing bradycardia, especially in children and after a repeat dose; atropine prevents or treats it. Dangerous hyperkalaemia mainly occurs in burns, crush injury and neuromuscular disease."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Nitrous Oxide Cylinder Contents","stem":"How should the anaesthetic technician best find out how much nitrous oxide is left in a cylinder?","options":["Read the pressure gauge on the cylinder","Feel for frost on the outside of the cylinder","Weigh it and subtract the empty (tare) weight","Look at the colour of the cylinder shoulder"],"correct":2,"explanation":"Nitrous oxide is stored as a liquid with vapour above it, so the gauge pressure stays nearly constant until all the liquid has evaporated and the cylinder is almost empty. Only weighing gives the true contents; the gauge works for oxygen because oxygen is stored as a gas."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Early Signs Of LAST","stem":"During an axillary brachial plexus block with bupivacaine, the patient says her lips feel numb and her ears are ringing. What should you do first?","options":["Inject the rest of the dose more slowly","Stop injecting, call for help and give oxygen","Give IV lidocaine to stabilise the heart","Reassure her that this is a normal block effect"],"correct":1,"explanation":"Numbness around the mouth and tinnitus are early CNS signs of local anaesthetic systemic toxicity (LAST). Stop the injection, call for help, give 100% oxygen and prepare lipid emulsion and seizure treatment; more local anaesthetic, including lidocaine, would worsen the toxicity."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Standard Blood Pressure Monitoring","stem":"According to ASA standards for basic anaesthetic monitoring, how often should arterial blood pressure be measured during general anaesthesia?","options":["At least every 15 minutes","At least every 30 minutes","Only at induction and at the end","At least every 5 minutes"],"correct":3,"explanation":"ASA standards require arterial blood pressure and heart rate to be measured at least every 5 minutes, together with continuous ECG, pulse oximetry and capnography. Measuring every 15 minutes could miss sudden hypotension after induction or bleeding."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"LAST Seizures","stem":"A patient having a large-volume bupivacaine block has a generalised seizure. BP is 125/75 mmHg and the airway is being managed with oxygen. Which drug should you give first for the seizure?","options":["Lidocaine IV bolus","Phenytoin IV infusion","Midazolam IV","Magnesium sulfate IV"],"correct":2,"explanation":"The ASRA checklist recommends a benzodiazepine first for LAST seizures (small propofol doses are an alternative if the circulation is stable), and lipid emulsion should be started early. Lidocaine adds to the toxicity, and phenytoin is not part of LAST treatment."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Pulse Oximetry and CO","stem":"A 30-year-old man rescued from a house fire needs urgent surgery. He is drowsy, and the pulse oximeter reads 99% on room air. What is the best interpretation?","options":["Oxygenation is normal, so no extra oxygen is needed","SpO2 is falsely low because of soot on his fingers","The normal reading rules out cyanide poisoning","SpO2 may be falsely high from carbon monoxide; give 100% oxygen"],"correct":3,"explanation":"Standard pulse oximeters read carboxyhaemoglobin as oxyhaemoglobin, so SpO2 can look normal while oxygen delivery is poor; give high-flow 100% oxygen and measure carboxyhaemoglobin by co-oximetry if available. A normal reading rules out neither carbon monoxide nor cyanide poisoning."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Lipid Emulsion Dose","stem":"A 60 kg woman develops serious local anaesthetic systemic toxicity. What initial bolus of 20% lipid emulsion does the ASRA checklist recommend?","options":["60 mL over 2 to 3 minutes","150 mL over 2 to 3 minutes","15 mL over 2 to 3 minutes","90 mL over 2 to 3 minutes"],"correct":3,"explanation":"For patients 70 kg or less, the bolus is 1.5 mL/kg: 1.5 x 60 = 90 mL over 2 to 3 minutes, followed by an infusion of 0.25 mL/kg/min (0.25 x 60 = 15 mL/min). 60 mL is only 1 mL/kg, and 15 mL is the per-minute infusion rate, not the bolus."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Blood Pressure Cuff Size","stem":"An obese woman's blood pressure is measured with a standard adult cuff that is too narrow for her arm. How will this affect the reading?","options":["It will read falsely high","It will not affect the reading","It will read falsely low","Only the heart rate will be wrong"],"correct":0,"explanation":"A cuff that is too narrow needs extra pressure to compress the artery, so it overestimates blood pressure; the bladder width should be about 40% of the arm circumference. A cuff that is too large tends to underestimate it."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Cardiac Arrest In LAST","stem":"A patient has a cardiac arrest from bupivacaine toxicity. CPR and lipid emulsion have started. Which change to standard advanced life support is recommended?","options":["Give a beta-blocker to control tachycardia","Give lidocaine for ventricular arrhythmias","Replace adrenaline with vasopressin 40 units","Use smaller adrenaline doses, under 1 mcg/kg"],"correct":3,"explanation":"The ASRA LAST checklist advises reducing each adrenaline dose to less than 1 mcg/kg and avoiding vasopressin, calcium channel blockers, beta-blockers and further local anaesthetic, so lidocaine is not used for arrhythmias (amiodarone is preferred)."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Arterial Transducer Level","stem":"A patient has an invasive arterial line. The transducer has slipped and is now 20 cm below the level of the heart. What will happen to the displayed blood pressure?","options":["It will read about 15 mmHg too high","It will read about 20 mmHg too high","It will read about 20 mmHg too low","It will read about 15 mmHg too low"],"correct":0,"explanation":"The transducer should be level with the heart (phlebostatic axis: 4th intercostal space, mid-axillary line). A 20 cm column of fluid adds 20 / 1.36 = about 15 mmHg, so the reading is falsely high; 20 mmHg confuses cmH2O with mmHg."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Bupivacaine Cardiotoxicity","stem":"Why is bupivacaine more cardiotoxic than lidocaine?","options":["It is excreted unchanged by the kidneys","It has a much faster onset than lidocaine","It is an ester that is broken down to PABA","It binds cardiac sodium channels strongly and leaves them slowly"],"correct":3,"explanation":"Bupivacaine is highly lipid-soluble and protein-bound and dissociates slowly from cardiac sodium channels ('fast in, slow out'), so its arrhythmias and cardiac arrest are hard to treat. It is an amide, not an ester, and its onset is slower than lidocaine's."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Oxytocin Side Effects","stem":"At caesarean section, 10 IU of oxytocin is given as a rapid IV push right after delivery. A minute later BP drops from 110/70 to 70/40 mmHg and HR rises to 130/min. What is the most likely cause?","options":["High spinal block","Anaphylaxis to oxytocin","Vasodilation from rapid IV oxytocin","Amniotic fluid embolism"],"correct":2,"explanation":"Oxytocin relaxes vascular smooth muscle, so a fast IV bolus causes hypotension with reflex tachycardia (and can cause myocardial ischaemia); it should be given slowly in a small dose. Amniotic fluid embolism usually brings sudden hypoxia, collapse and bleeding problems rather than a drug-timed drop in BP."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Choice of Oxygen Device","stem":"A trauma patient is breathing spontaneously with an SpO2 of 84% on room air. Which device will deliver the highest inspired oxygen concentration?","options":["Venturi mask set at 40%","Non-rebreathing mask with reservoir bag at 15 L/min","Nasal cannula at 6 L/min","Simple face mask at 6 L/min"],"correct":1,"explanation":"A mask with a reservoir bag and one-way valves at 15 L/min gives the highest FiO2 (roughly 60-90%) without intubation. Nasal cannula at 6 L/min gives only about 40-45%, and a simple face mask at 6 L/min also gives far less than a reservoir mask."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Maternal Cardiac Arrest","stem":"A woman at 34 weeks' gestation has a cardiac arrest on the ward. CPR is started with manual left uterine displacement. There is no return of circulation after 4 minutes. What is the best next step?","options":["Stop compressions and turn her fully onto her left side","Perform a perimortem caesarean delivery, aiming to deliver within 5 minutes of arrest","Wait until the fetal heart is confirmed with ultrasound","Continue CPR for 20 minutes before considering delivery"],"correct":1,"explanation":"After 20 weeks, if there is no return of circulation within 4 minutes, emergency hysterotomy should be done aiming for delivery by 5 minutes; emptying the uterus relieves aortocaval compression and improves maternal CPR. Waiting 20 minutes or checking the fetus wastes the time when the mother can still be saved."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Oxygen in COPD","stem":"A 68-year-old man with known COPD and previous CO2 retention is admitted with an exacerbation. His SpO2 is 82% on air. What oxygen plan is most appropriate?","options":["Controlled oxygen by Venturi mask, aiming for SpO2 88-92%","No oxygen until an arterial blood gas result is available","Nasal cannula at 6 L/min, aiming for SpO2 94-98%","Non-rebreathing mask at 15 L/min, aiming for SpO2 98-100%"],"correct":0,"explanation":"In patients at risk of hypercapnic respiratory failure, oxygen is given in a controlled way (e.g. Venturi 24-28%) to a target SpO2 of 88-92%, then adjusted using a blood gas. Withholding oxygen is dangerous, and aiming for 98-100% can worsen CO2 retention and acidosis."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Total Spinal After Top-Up","stem":"A woman with a working labour epidural receives 20 mL of 2% lidocaine through the catheter for an urgent caesarean section. Within 3 minutes she cannot lift her arms, is short of breath, and BP is 65/30 mmHg. What is the most likely cause?","options":["Vasovagal faint caused by anxiety","Amniotic fluid embolism","Local anaesthetic toxicity from intravascular injection","Total spinal from a catheter that had moved into the subarachnoid space"],"correct":3,"explanation":"A fast, dense motor block of the arms and breathing with severe hypotension means the epidural dose went intrathecally; this is why top-ups are given in increments. Local anaesthetic toxicity presents with perioral numbness, tinnitus, seizures and arrhythmias, not a dense motor block."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Oxygen Cylinder Duration","stem":"A patient on 10 L/min of oxygen is being transferred from the district hospital to a referral hospital. The cylinder holds 680 litres when full, and the gauge shows it is half full. About how long will the oxygen last?","options":["68 minutes","136 minutes","17 minutes","34 minutes"],"correct":3,"explanation":"Half of 680 L = 340 L; 340 L / 10 L per minute = 34 minutes, so a spare cylinder is needed for the journey. 68 minutes is the time a full cylinder would last at this flow."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Newborn Resuscitation","stem":"A baby is delivered by caesarean section under general anaesthesia. After drying and stimulation the baby is not breathing and the heart rate is 80/min. What should be done next?","options":["Start chest compressions at 3 compressions to 1 breath","Give naloxone to reverse the anaesthetic drugs","Give adrenaline through the umbilical vein","Open the airway and start bag-and-mask ventilation"],"correct":3,"explanation":"Effective ventilation is the key step in newborn resuscitation; most babies respond with a rising heart rate. Chest compressions start only if HR stays below 60/min despite 30 seconds of effective ventilation, and naloxone is not a routine resuscitation drug."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Shunt and Hypoxaemia","stem":"A patient with dense right lower lobe pneumonia has an SpO2 of 85%. Increasing the FiO2 from 0.4 to 1.0 raises the SpO2 only slightly. What is the main mechanism of the hypoxaemia?","options":["Hypoventilation from respiratory depression","Shunt through alveoli that are not ventilated","Low inspired oxygen pressure","Diffusion impairment across a thickened membrane"],"correct":1,"explanation":"In a true shunt, blood passes through collapsed or fluid-filled alveoli that never receive the extra oxygen, so raising the FiO2 helps very little. Hypoxaemia from hypoventilation or diffusion impairment improves well with added oxygen."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Volatile Agents And Uterus","stem":"During caesarean section under general anaesthesia, the baby has been delivered and oxytocin given, but the uterus remains soft and bleeding continues. Isoflurane is at 1.5 MAC. Which anaesthetic change helps most?","options":["Stop the IV fluids to reduce bleeding","Reduce isoflurane to about 0.5–0.75 MAC and add an IV opioid","Increase isoflurane to 2 MAC to deepen anaesthesia","Give a second dose of suxamethonium"],"correct":1,"explanation":"Volatile agents relax the uterus in a dose-dependent way, so after delivery reduce them and keep the patient asleep with an opioid (or nitrous oxide). Increasing the volatile would worsen uterine atony and bleeding."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Preventing Airway Fire","stem":"During a surgical tracheostomy in ICU, the surgeon plans to use diathermy near the airway. The patient is being ventilated with 100% oxygen. Which change to the gas mixture best reduces the risk of an airway fire?","options":["Reduce the oxygen to the lowest safe level, ideally 30% or less","Increase the fresh gas flow to cool the airway","Keep 100% oxygen to protect against hypoxia","Replace part of the oxygen with nitrous oxide"],"correct":0,"explanation":"Fire needs an oxidiser, a fuel and an ignition source; lowering the inspired oxygen (to 30% or less if SpO2 allows) for a few minutes before diathermy near the airway reduces the oxidiser. Nitrous oxide also supports combustion, so using it in place of oxygen does not reduce the risk, and keeping 100% oxygen makes fire much more likely."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric Tracheal Tube Size","stem":"A 6-year-old boy needs an uncuffed tracheal tube for tonsillectomy. Using the age formula, what internal diameter should you choose?","options":["6.5 mm","5.0 mm","5.5 mm","4.5 mm"],"correct":2,"explanation":"Uncuffed tube size = (age ÷ 4) + 4 = (6 ÷ 4) + 4 = 1.5 + 4 = 5.5 mm; have a half size above and below ready. 6.5 mm is too large: it is the formula size for a 10-year-old."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Cyanide in Smoke Inhalation","stem":"A man rescued after a long time in a closed burning room is confused, with BP 80/50 mmHg and a lactate of 11 mmol/L despite 100% oxygen. Cyanide poisoning is suspected. Which antidote should be given?","options":["Sodium bicarbonate IV only","Naloxone IV","Hydroxocobalamin IV","Methylene blue IV"],"correct":2,"explanation":"Burning plastics, wool and furnishings release hydrogen cyanide, which blocks cellular oxygen use and causes severe lactic acidosis and shock; hydroxocobalamin (5 g IV in adults) binds cyanide to form cyanocobalamin, which is excreted in urine. Methylene blue treats methaemoglobinaemia, and bicarbonate alone does not remove the cause of the acidosis."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric Maintenance Fluids","stem":"A 22 kg child is fasting before surgery. Using the 4-2-1 rule, what is the hourly maintenance fluid rate?","options":["88 mL/h","62 mL/h","55 mL/h","70 mL/h"],"correct":1,"explanation":"4 mL/kg/h for the first 10 kg = 40, plus 2 mL/kg/h for the next 10 kg = 20, plus 1 mL/kg/h for the remaining 2 kg = 2; total 62 mL/h. 88 mL/h comes from wrongly giving 4 mL/kg/h for all 22 kg."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Oxygen in Preterm Babies","stem":"A baby born at 28 weeks needs supplemental oxygen in the neonatal unit. Why must the oxygen be carefully titrated with SpO2 monitoring rather than given freely?","options":["Oxygen stops the breathing drive of all newborns","Oxygen makes neonatal hypoglycaemia much worse","Oxygen is a common cause of neonatal jaundice","High oxygen levels can damage the developing retinal vessels"],"correct":3,"explanation":"In preterm babies, too much oxygen (hyperoxia) damages the immature retinal blood vessels and causes retinopathy of prematurity, which can lead to blindness; it also adds to chronic lung disease. Oxygen does not cause jaundice or hypoglycaemia."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric IM Adrenaline Dose","stem":"A 15 kg child develops anaphylaxis with wheeze, lip swelling and low blood pressure after an IV antibiotic. You will give IM adrenaline 10 micrograms/kg using the 1 mg/mL (1:1000) ampoule. What volume do you give?","options":["0.5 mL","1.5 mL","0.015 mL","0.15 mL"],"correct":3,"explanation":"Dose = 10 micrograms x 15 kg = 150 micrograms = 0.15 mg; at 1 mg/mL the volume is 0.15 mL, given into the anterolateral thigh and repeated after 5 minutes if needed. 1.5 mL is a tenfold overdose (the volume that would be needed of a 1:10,000 solution), and 0.5 mL is the adult dose."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Humidification via Tracheostomy","stem":"A patient with a new tracheostomy in ICU is receiving oxygen. Why must the inspired gas be humidified?","options":["The nose is bypassed, so dry gas thickens secretions that can block the tube","Humidification lowers the work of breathing by cooling the airway","Humidification prevents bacteria entering the tube","Humid gas carries a higher oxygen concentration"],"correct":0,"explanation":"The nose and upper airway normally warm and humidify inspired air; with a tracheostomy they are bypassed, so dry gas dries the mucosa and thickens secretions that can plug the tube. Humidification does not raise the oxygen concentration or sterilise the gas."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric Cardiac Arrest Drugs","stem":"A 20 kg child is in cardiac arrest with asystole. What volume of adrenaline 1:10,000 (100 micrograms/mL) should be given IV?","options":["20 mL","2 mL","0.2 mL","1 mL"],"correct":1,"explanation":"Adrenaline dose = 10 micrograms/kg × 20 kg = 200 micrograms; 200 ÷ 100 micrograms/mL = 2 mL (0.1 mL/kg of 1:10,000). 0.2 mL would give only 20 micrograms, a tenfold underdose."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Glasgow Coma Scale","stem":"A head-injured patient opens his eyes only to pressure, uses inappropriate words, and withdraws his arm from a painful stimulus. What is his Glasgow Coma Scale score?","options":["7","9","10","8"],"correct":1,"explanation":"Eyes open to pressure = 2, inappropriate words = 3, withdrawal (normal flexion) = 4, so GCS = 2 + 3 + 4 = 9. A score of 8 would result from wrongly scoring withdrawal as abnormal flexion (3)."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Allowable Blood Loss","stem":"A 10 kg one-year-old has a haematocrit of 36%. Taking blood volume as 80 mL/kg, what is the maximum allowable blood loss if the lowest acceptable haematocrit is 27%?","options":["100 mL","400 mL","200 mL","300 mL"],"correct":2,"explanation":"Blood volume = 80 × 10 = 800 mL; MABL = 800 × (36 − 27) ÷ 36 = 800 × 0.25 = 200 mL. A common error is to divide by the final haematocrit (27) instead of the starting one (36)."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Airway in Head Injury","stem":"A 25-year-old with a severe head injury has a GCS of 7. He is snoring, and his SpO2 is 92% on a face mask. What is the most important next step?","options":["Secure the airway with tracheal intubation while keeping the neck in line","Send him for CT scan first, then decide about the airway","Insert a nasopharyngeal airway and admit him to the ward","Give IV mannitol, then reassess his breathing in one hour"],"correct":0,"explanation":"A GCS of 8 or less means the patient cannot protect his airway, and hypoxia and high CO2 worsen brain injury, so he needs a definitive airway (rapid sequence intubation with manual in-line stabilisation). Going to CT with an unprotected airway risks aspiration and hypoxia on the way."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Infant Airway Anatomy","stem":"Why is a straight-blade laryngoscope (e.g. Miller) often preferred for intubating an infant?","options":["The infant's long, floppy epiglottis is best lifted directly with the blade tip","The infant's tongue is relatively small for the mouth","The infant's trachea is longer, so a deeper view is needed","The infant's larynx is lower in the neck than an adult's"],"correct":0,"explanation":"Infants have a long, floppy, U-shaped epiglottis and a high, anterior larynx (about C3–C4), so lifting the epiglottis directly with a straight blade gives a better view. The infant tongue is relatively large and the trachea is short, not long."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Preventing Ventilator Pneumonia","stem":"Which nursing measure helps most to prevent ventilator-associated pneumonia in an intubated ICU patient?","options":["Changing the ventilator circuit every day","Giving prophylactic antibiotics to every ventilated patient","Raising the head of the bed to 30-45 degrees","Keeping the patient lying flat to protect the spine"],"correct":2,"explanation":"Nursing the patient semi-recumbent (head up 30-45 degrees) reduces aspiration of stomach contents and oral secretions past the cuff. Routine daily circuit changes do not reduce pneumonia, and routine antibiotics promote resistant organisms."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Infant Oxygen Reserve","stem":"Why does a 6-month-old baby desaturate much faster than an adult during apnoea at induction?","options":["Fetal haemoglobin cannot carry oxygen","The baby has a higher functional residual capacity per kg","The baby breathes mainly with intercostal muscles","Oxygen consumption per kg is about twice the adult value"],"correct":3,"explanation":"Infant oxygen consumption is about 6 mL/kg/min compared with about 3 mL/kg/min in adults, so the small oxygen store is used up quickly. FRC per kg is not higher, and infants rely mainly on the diaphragm, not intercostal muscles."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Lung-Protective Tidal Volume","stem":"A man 170 cm tall who weighs 95 kg is ventilated for ARDS. His predicted body weight is 50 + 0.91 x (height in cm - 152.4). What initial tidal volume should be set at 6 mL/kg predicted body weight?","options":["About 400 mL","About 660 mL","About 950 mL","About 570 mL"],"correct":0,"explanation":"PBW = 50 + 0.91 x (170 - 152.4) = 50 + 0.91 x 17.6 = 50 + 16 = 66 kg; 6 mL/kg x 66 kg = about 400 mL. Using the actual weight (6 x 95 = 570 mL) over-distends the lungs, because lung size depends on height, not body weight."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Bradycardia During Induction","stem":"During inhalational induction with sevoflurane, a 1-year-old's heart rate falls from 150 to 70/min and SpO2 is 80%. What should you do first?","options":["Open and secure the airway and ventilate with 100% oxygen","Start chest compressions immediately","Give IV adrenaline 10 micrograms/kg","Check the pulse oximeter probe and wait for a better reading"],"correct":0,"explanation":"Hypoxia is the commonest cause of bradycardia in small children, and infant cardiac output depends on heart rate, so the first step is to correct oxygenation. Compressions are needed if HR stays below 60/min with poor perfusion despite good oxygenation."},
    ],
  },
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-anaesthesia-licensing-exam","name":"Anaesthesia Licensing Exam (RAHPC)"},
    slug: "rahpc-anaesthesia-mock-exam-4",
    title: "Anaesthesia Licensing Exam (RAHPC) — Mock Exam 4",
    summary: "Anaesthetic Pharmacology and General Anaesthesia; Regional Anaesthesia, Critical Care and Resuscitation.",
    free: false, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover anaesthesia practice."],
    sections: [{"name":"Anaesthetic Pharmacology and General Anaesthesia"},{"name":"Regional Anaesthesia, Critical Care and Resuscitation"}],
    questions: [
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Phase I Depolarising Block","stem":"A few minutes after suxamethonium 1.5 mg/kg, train-of-four stimulation is applied at the ulnar nerve. Which pattern is expected with this normal (phase I) block?","options":["A strong first twitch with the other three absent","Fade of the four twitches, with post-tetanic potentiation","Four twitches that grow taller from the first to the fourth","Four equally reduced twitches with no fade"],"correct":3,"explanation":"A phase I depolarising block reduces all four twitches equally, with no fade and no post-tetanic potentiation. Fade with post-tetanic potentiation is typical of a non-depolarising block, or of a phase II block after large or repeated doses of suxamethonium."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Adrenaline With Lidocaine","stem":"The maximum safe dose of lidocaine is higher when it is mixed with adrenaline. Why?","options":["Vasoconstriction slows its absorption into the blood","Adrenaline speeds up its breakdown in the liver","Adrenaline blocks its effects on the heart","Adrenaline increases its binding to proteins"],"correct":0,"explanation":"Adrenaline constricts local blood vessels, so lidocaine is absorbed more slowly and peak plasma levels are lower; it also prolongs the block. Adrenaline does not change lidocaine's metabolism, cardiac effects or protein binding."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Perioperative Hypothermia Effects","stem":"A 65-year-old has a 4-hour open abdominal operation without active warming, and his core temperature falls to 34.5 degrees C. Which effect is most likely?","options":["Lower oxygen use in the recovery room","More surgical bleeding from impaired clotting","Faster recovery from muscle relaxants","Better protection against surgical wound infection"],"correct":1,"explanation":"Mild hypothermia impairs platelet function and clotting enzymes, increasing blood loss. It also raises (not lowers) wound infection risk, slows drug metabolism so muscle relaxants last longer, and causes shivering in recovery that increases oxygen use."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Local Anaesthetic Allergy","stem":"A woman had a documented allergic reaction (urticaria and wheeze) to procaine at a dentist. Which local anaesthetic is most suitable for her spinal anaesthetic?","options":["Hyperbaric bupivacaine","Procaine in a lower dose","Tetracaine","Chloroprocaine"],"correct":0,"explanation":"Ester local anaesthetics (procaine, chloroprocaine, tetracaine) are broken down to para-aminobenzoic acid (PABA), which causes most true local anaesthetic allergies, and cross-reaction between esters is common. Amides such as bupivacaine rarely cause allergy and do not cross-react with esters."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"ECG Lead for Ischaemia","stem":"In a patient with coronary artery disease, which single ECG lead is most sensitive for detecting left ventricular ischaemia during anaesthesia?","options":["Lead II","aVR","V1","V5"],"correct":3,"explanation":"V5 lies over the left ventricle and detects most intraoperative ischaemic episodes, and combining it with lead II detects more. Lead II is best for seeing P waves, arrhythmias and inferior ischaemia, but alone it is less sensitive for left ventricular ischaemia."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Prilocaine Methaemoglobinaemia","stem":"After a large dose of prilocaine for IV regional anaesthesia, a patient looks blue with SpO2 85% that does not improve with oxygen, and his blood is chocolate-brown. What is the best treatment?","options":["20% lipid emulsion IV","Methylene blue IV","Sodium bicarbonate IV","Naloxone IV"],"correct":1,"explanation":"Prilocaine is metabolised to o-toluidine, which oxidises haemoglobin to methaemoglobin; significant methaemoglobinaemia is treated with IV methylene blue (1 to 2 mg/kg). Lipid emulsion treats local anaesthetic systemic toxicity, not methaemoglobinaemia."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Intraoperative Urine Output","stem":"A 70-kg patient with a urinary catheter has a 3-hour laparotomy. What is the minimum total urine output that suggests adequate kidney perfusion over the 3 hours?","options":["210 mL","350 mL","105 mL","35 mL"],"correct":2,"explanation":"The usual minimum target is 0.5 mL/kg/h: 0.5 x 70 kg x 3 h = 105 mL. 35 mL is the minimum for one hour only, and 210 mL uses 1 mL/kg/h, a target often used in children."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Aspiration Prophylaxis","stem":"A woman is having an emergency caesarean section under general anaesthesia. Which drug is given just before induction to neutralise stomach acid?","options":["Metoclopramide 10 mg IV","Magnesium trisilicate mixture by mouth","Omeprazole 40 mg by mouth","Sodium citrate 0.3 M, 30 mL by mouth"],"correct":3,"explanation":"Sodium citrate is a clear, non-particulate antacid that raises gastric pH immediately. Particulate antacids such as magnesium trisilicate cause severe lung injury if aspirated, and omeprazole and metoclopramide take time to work and do not neutralise acid already in the stomach."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Oxygen Dissociation Curve","stem":"Why should an SpO2 that falls below 90% during anaesthesia be acted on quickly?","options":["Below this level, the heart rate always falls to dangerous values","Below this level, carbon dioxide always rises sharply in the blood","Below this level, the pulse oximeter stops giving any reading","Below this level, small falls in PaO2 cause large falls in saturation"],"correct":3,"explanation":"An SpO2 of about 90% matches a PaO2 of about 8 kPa (60 mmHg), where the oxyhaemoglobin dissociation curve becomes steep, so oxygen content falls fast with any further drop. Carbon dioxide retention is a separate problem that SpO2 does not show."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Glycopyrrolate Versus Atropine","stem":"An 80-year-old needs a drug to dry secretions before awake fibreoptic intubation. Why is glycopyrrolate preferred to atropine?","options":["It has a shorter action than atropine","It also gives useful sedation","It produces a bigger rise in heart rate","It does not enter the brain, so it causes less confusion"],"correct":3,"explanation":"Glycopyrrolate is a quaternary amine that does not cross the blood-brain barrier, so it avoids the central anticholinergic confusion atropine can cause in the elderly; it is also a strong drying agent with less tachycardia. It acts longer, not shorter, than atropine and has no sedative effect."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Confirming Tracheal Intubation","stem":"After intubating a patient at a district hospital, what is the most reliable way to confirm that the tube is in the trachea?","options":["A sustained waveform on capnography over several breaths","Breath sounds heard over both lungs with a stethoscope","Equal chest rise seen on both sides of the chest","Misting seen inside the tube during expiration"],"correct":0,"explanation":"A persistent capnography trace with every breath is the standard for confirming tracheal placement ('no trace = wrong place'). Chest rise, breath sounds and misting can all be present with a tube in the oesophagus."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Paediatric Premedication","stem":"A very anxious 4-year-old is booked for elective surgery and has no IV line. Which premedication is most appropriate?","options":["Oral diazepam the night before only","Oral midazolam about 30 minutes before induction","Intramuscular morphine 1 hour before induction","IV ketamine given on the ward"],"correct":1,"explanation":"Oral midazolam gives anxiolysis within about 20 to 30 minutes and is the most widely used paediatric premedication. Intramuscular injections are painful and frightening for children, and IV ketamine on an unmonitored ward is unsafe."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Sudden Loss of Capnogram","stem":"During ventilation through a tracheal tube, the capnography trace suddenly drops to zero, the low airway pressure alarm sounds, and the SpO2 is still 99%. What is the most likely cause?","options":["Exhausted soda lime","Severe bronchospasm","Onset of malignant hyperthermia","Disconnection of the breathing circuit"],"correct":3,"explanation":"A sudden loss of the CO2 trace with low airway pressure means gas is not reaching the patient, most often a circuit disconnection; SpO2 falls only later because of oxygen stores. Bronchospasm causes high airway pressure and a sloping 'shark-fin' trace rather than a flat line."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Regular Medicines Before Surgery","stem":"A 62-year-old is booked for an elective hernia repair under spinal anaesthesia. Which regular medicine should normally be taken on the morning of surgery?","options":["Rivaroxaban","Warfarin","Clopidogrel","Atenolol"],"correct":3,"explanation":"Beta-blockers should be continued around surgery, because stopping them suddenly can cause rebound tachycardia and myocardial ischaemia. Warfarin, rivaroxaban and clopidogrel must be stopped in advance before a spinal because of the risk of spinal haematoma."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Falling End-Tidal CO2","stem":"During a cemented hip hemiarthroplasty, just after the cement is inserted, the end-tidal CO2 falls from 38 to 18 mmHg, the blood pressure falls to 70/40 mmHg and the SpO2 drops. Ventilator settings are unchanged. What is the most likely cause?","options":["Emboli reducing lung blood flow (bone cement implantation)","Accidental hyperventilation by the anaesthetic ventilator","Rebreathing of CO2 from exhausted soda lime","Disconnection of the circuit at the Y-piece"],"correct":0,"explanation":"A sudden fall in end-tidal CO2 with hypotension and hypoxia at cementing suggests emboli blocking pulmonary blood flow, which increases dead space and lowers cardiac output. The ventilator settings are unchanged, so hyperventilation is unlikely, and a disconnection would give a flat trace with low airway pressure."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Preoperative Fasting","stem":"A healthy adult booked for elective surgery had tea with milk and bread at 06:00. Following ASA fasting guidelines, what is the earliest time anaesthesia can start?","options":["12:00","08:00","10:00","14:00"],"correct":0,"explanation":"A light meal (such as bread and tea with milk) needs at least 6 hours: 06:00 + 6 hours = 12:00. Two hours (08:00) applies only to clear fluids, and 8 hours applies to fried or fatty food."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Raised Capnograph Baseline","stem":"On the capnograph, the baseline no longer returns to zero during inspiration, and the inspired CO2 reads 6 mmHg. What is the most likely cause?","options":["The tracheal tube has slipped into the oesophagus","Rebreathing from exhausted soda lime or a faulty valve","A sudden fall in the patient's cardiac output","A leak around the cuff of the tracheal tube"],"correct":1,"explanation":"A raised baseline means CO2 is being breathed in again; in a circle system the usual causes are exhausted soda lime or a sticking one-way valve, so check and change the soda lime or increase fresh gas flow. A cuff leak or a fall in cardiac output lowers the end-tidal value but does not raise the baseline."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Prokinetic Premedication","stem":"A 50-year-old diabetic with gastroparesis needs emergency surgery. Which drug reduces aspiration risk mainly by speeding gastric emptying and raising lower oesophageal sphincter tone?","options":["Omeprazole","Metoclopramide","Glycopyrrolate","Sodium citrate"],"correct":1,"explanation":"Metoclopramide is a dopamine-antagonist prokinetic that speeds gastric emptying and increases lower oesophageal sphincter tone. Omeprazole and sodium citrate reduce acidity rather than stomach volume, and glycopyrrolate slows gastric emptying."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Shark-Fin Capnogram","stem":"A 30-year-old woman with asthma is ventilated after intubation. The capnograph shows a slowly rising 'shark-fin' upstroke and the airway pressure is high. What is the most likely problem?","options":["Bronchospasm slowing expiration","Malignant hyperthermia","Return of spontaneous breathing","Disconnection of the circuit"],"correct":0,"explanation":"A sloping upstroke (shark fin) means slow, uneven emptying of the alveoli, typical of bronchospasm or COPD, and the high airway pressure supports this. Spontaneous breathing efforts cause a notch in the plateau (curare cleft), not a shark fin."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Perioperative Steroid Cover","stem":"A 45-year-old who has taken prednisolone 20 mg daily for a year forgot his morning dose. During surgery he becomes hypotensive and does not respond to fluids or vasopressors. Which drug is most appropriate?","options":["An adrenaline infusion alone","Sodium bicarbonate IV","Hydrocortisone IV","Calcium gluconate IV"],"correct":2,"explanation":"Long-term steroids suppress the adrenal glands; without his usual dose, surgical stress can cause an adrenal crisis, which presents as hypotension that does not respond to fluids or vasopressors. It is treated with IV hydrocortisone (for example 100 mg); vasopressors alone do not replace the missing cortisol."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Curare Cleft","stem":"Forty minutes after a single dose of rocuronium, a notch (cleft) appears in the plateau of the capnography trace during mechanical ventilation. What does this most likely mean?","options":["The soda lime is exhausted and needs to be changed","The patient is making breathing efforts as the block wears off","The tracheal tube has moved down into the oesophagus","The patient is developing malignant hyperthermia"],"correct":1,"explanation":"A curare cleft is caused by the patient's own diaphragm movements drawing in gas during the plateau, showing that the neuromuscular block is wearing off; check the depth of anaesthesia and the need for more relaxant. Exhausted soda lime raises the baseline instead."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Benzodiazepine Reversal","stem":"A child given oral midazolam premedication becomes very sleepy, with RR 10/min and SpO2 91% on air. After positioning the airway and giving oxygen, which drug reverses the midazolam?","options":["Atropine","Naloxone","Flumazenil","Neostigmine"],"correct":2,"explanation":"Flumazenil is a competitive benzodiazepine antagonist; its action is shorter than midazolam's, so the child must be watched for re-sedation. Naloxone reverses opioids, not benzodiazepines."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Rising ETCO2 at Laparoscopy","stem":"During a laparoscopic cholecystectomy with CO2 pneumoperitoneum, the end-tidal CO2 rises slowly from 35 to 46 mmHg over 30 minutes with unchanged ventilator settings. Inspired CO2 is zero, heart rate and temperature are stable and there is no muscle rigidity. What is the most likely cause?","options":["Exhausted soda lime causing rebreathing","Hypothermia from cold insufflated gas","Absorption of the insufflated CO2 from the peritoneum","Malignant hyperthermia starting"],"correct":2,"explanation":"CO2 used to inflate the abdomen is absorbed into the blood, so end-tidal CO2 rises gradually; this is managed by increasing minute ventilation. Exhausted soda lime gives an inspired CO2 above zero, malignant hyperthermia comes with tachycardia, rigidity and a rapid rise, and hypothermia lowers CO2 production rather than raising it."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Early Sign Of MH","stem":"A patient is anaesthetised with sevoflurane after suxamethonium. Which is usually the earliest sign of malignant hyperthermia?","options":["Dark cola-coloured urine","End-tidal CO2 rising despite more ventilation","Widespread rash and bronchospasm","Body temperature above 40°C"],"correct":1,"explanation":"An unexplained rise in end-tidal CO2 that does not settle with increased minute ventilation, often with tachycardia and muscle rigidity, is the earliest and most sensitive sign. High temperature and myoglobinuria usually come later, and rash with bronchospasm suggests anaphylaxis."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Capnography During CPR","stem":"During CPR in theatre, the end-tidal CO2 has been about 15 mmHg. It suddenly rises to 40 mmHg. What does this most likely mean?","options":["The tracheal tube has become dislodged","The ventilation rate has become too fast","Chest compressions have become weaker","Return of spontaneous circulation"],"correct":3,"explanation":"During CPR, end-tidal CO2 reflects blood flow through the lungs, so a sudden sustained rise is an early sign of return of spontaneous circulation; look for other signs such as a pulse and rising blood pressure. A dislodged tube, weaker compressions or faster ventilation would all lower end-tidal CO2."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"ARDS Severity","stem":"A ventilated patient with bilateral lung infiltrates not explained by heart failure has a PaO2 of 75 mmHg (10 kPa) on an FiO2 of 0.5 with PEEP of 8 cmH2O. Using the Berlin definition, how severe is the ARDS?","options":["Not ARDS, because the PaO2 is above 60 mmHg","Moderate","Mild","Severe"],"correct":1,"explanation":"PaO2/FiO2 = 75 / 0.5 = 150 mmHg, which lies in the moderate range (100-200 mmHg with PEEP of at least 5). Mild is 200-300 mmHg and severe is 100 mmHg or less; the PaO2 alone, without the FiO2, does not define ARDS."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric Tube Length","stem":"A 4-year-old is intubated orally for adenotonsillectomy. Using the standard age formula, at what length at the lips should the tube be fixed, before you check breath sounds?","options":["12 cm","14 cm","20 cm","17 cm"],"correct":1,"explanation":"Oral tube length (cm at the lips) = (age ÷ 2) + 12 = (4 ÷ 2) + 12 = 14 cm; position is then confirmed with capnography and equal breath sounds on both sides. 17 cm is the nasal tube length ((age ÷ 2) + 15), and a tube fixed too deep tends to enter the right main bronchus."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"High Airway Pressure","stem":"In a volume-controlled ventilated patient, the peak airway pressure rises from 22 to 40 cmH2O, but the plateau pressure stays at 18 cmH2O. What is the most likely cause?","options":["A tension pneumothorax","The tube has moved into the right main bronchus","A mucus plug or a kink in the tracheal tube","Worsening pulmonary oedema"],"correct":2,"explanation":"A rise in peak pressure with an unchanged plateau pressure means higher airway resistance (secretions, kinked or bitten tube, bronchospasm). Pneumothorax, pulmonary oedema and endobronchial intubation reduce lung compliance, so the plateau pressure would rise as well."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Pyloric Stenosis","stem":"A 5-week-old boy has projectile non-bilious vomiting and a palpable pyloric 'olive'. Na 131 mmol/L, Cl 84 mmol/L, K 2.9 mmol/L, HCO3 35 mmol/L. When should pyloromyotomy be done?","options":["Immediately tonight, as it is a surgical emergency","Only after a week of nasogastric feeding to gain weight","After IV fluid and potassium correction, once chloride and bicarbonate are near normal","After giving IV sodium bicarbonate to correct the acid–base problem"],"correct":2,"explanation":"Pyloric stenosis is a medical, not surgical, emergency: the hypochloraemic, hypokalaemic metabolic alkalosis must be corrected first (e.g. 0.9% saline with dextrose and potassium), as alkalosis increases the risk of apnoea after anaesthesia. The baby is already alkalotic, so bicarbonate would make it worse."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Sudden Desaturation on Ventilator","stem":"A ventilated ICU patient suddenly desaturates to 80% and the ventilator high-pressure alarm sounds. What should you do first?","options":["Disconnect the ventilator and hand-ventilate with 100% oxygen","Give a bolus of sedation and wait 5 minutes","Order an urgent portable chest X-ray","Increase the PEEP to 15 cmH2O"],"correct":0,"explanation":"Hand-ventilating with 100% oxygen supports the patient and quickly tells you whether the problem is the machine or the patient; then work through DOPE (Displacement, Obstruction, Pneumothorax, Equipment). An X-ray or PEEP change delays treatment of a blocked or displaced tube."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Neonatal Hypothermia","stem":"A term neonate is in a cool theatre for surgery. Which statement best explains why the baby gets cold quickly?","options":["The baby shivers strongly and uses up energy","Neonates cannot lose heat by radiation","Large surface area for weight, little insulating fat, and no effective shivering","Babies have a lower surface area to weight ratio than adults"],"correct":2,"explanation":"Neonates have a large surface area relative to weight, thin skin and little fat, and cannot shiver; they rely on brown fat (non-shivering thermogenesis), which raises oxygen consumption. Their surface area to weight ratio is higher than adults, not lower, and radiation is a major route of heat loss."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Glucose Control in ICU","stem":"A ventilated adult in ICU has persistent hyperglycaemia and an insulin infusion is started. Which blood glucose target range is recommended?","options":["12-15 mmol/L (216-270 mg/dL)","Below 4 mmol/L (72 mg/dL)","4.4-6.1 mmol/L (80-110 mg/dL)","7.8-10 mmol/L (140-180 mg/dL)"],"correct":3,"explanation":"For most critically ill adults, glucose is kept at about 7.8-10 mmol/L (140-180 mg/dL). Tight control at 4.4-6.1 mmol/L increased deaths and severe hypoglycaemia in the NICE-SUGAR trial."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Caudal Block Anatomy","stem":"During a caudal block in a 3-year-old, a 'give' is felt as the needle enters the caudal epidural space. Which structure has the needle just passed through?","options":["Sacrococcygeal ligament covering the sacral hiatus","Supraspinous ligament","Ligamentum flavum at L5–S1","Posterior longitudinal ligament"],"correct":0,"explanation":"The caudal needle enters through the sacral hiatus between the sacral cornua, and the 'give' is felt as it pierces the sacrococcygeal ligament. The ligamentum flavum is crossed in lumbar epidurals, not caudal blocks."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Opioid Respiratory Acidosis","stem":"After a morphine bolus on the ward, a post-operative patient is very drowsy with a respiratory rate of 6/min. Arterial gas: pH 7.25, PaCO2 60 mmHg (8 kPa), HCO3- 26 mmol/L. What does this show?","options":["Acute respiratory acidosis","Metabolic acidosis with respiratory compensation","Compensated respiratory alkalosis","Metabolic alkalosis"],"correct":0,"explanation":"Low pH with a high PaCO2 is respiratory acidosis, and the near-normal bicarbonate shows the kidneys have not yet compensated, so it is acute, here from opioid-induced hypoventilation. In metabolic acidosis the bicarbonate would be low and the PaCO2 low, not high."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Neonatal Spinal Anaesthesia","stem":"You plan a spinal anaesthetic for inguinal hernia repair in a 2-week-old ex-preterm baby. Why should you use the L4–L5 or L5–S1 space?","options":["The spinal cord may end as low as L3 in neonates","The epidural space is absent above L3 in neonates","The dural sac ends at L1 in neonates","CSF volume per kg is lower in neonates"],"correct":0,"explanation":"At birth the spinal cord may end as low as L3 (reaching the adult L1–L2 level in the first year), so a low space avoids cord injury. The dural sac also ends lower (about S3), and CSF volume per kg is higher in neonates, not lower."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Anion Gap Calculation","stem":"A 19-year-old with diabetes is drowsy and breathing deeply. Na+ 136 mmol/L, Cl- 100 mmol/L, HCO3- 8 mmol/L. What is the anion gap and what type of acidosis is this?","options":["28 mmol/L; normal anion gap acidosis","12 mmol/L; normal anion gap acidosis","28 mmol/L; high anion gap acidosis","44 mmol/L; high anion gap acidosis"],"correct":2,"explanation":"Anion gap = Na+ - (Cl- + HCO3-) = 136 - (100 + 8) = 28 mmol/L, well above the normal of about 8-12, so this is a high anion gap metabolic acidosis, as in diabetic ketoacidosis. 44 comes from wrongly adding the bicarbonate instead of subtracting it."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric Fasting","stem":"A 6-month-old exclusively breastfed baby was last fed at 06:00. She is booked for elective hernia repair. Following the ASA fasting guidance (clear fluids 2 hours, breast milk 4 hours, formula or food 6 hours), what is the earliest time anaesthesia can be induced?","options":["12:00","07:00","08:00","10:00"],"correct":3,"explanation":"Under the ASA guidance breast milk needs a 4-hour fast: 06:00 + 4 hours = 10:00. Waiting until 12:00 (6 hours, the rule for formula or solid food) prolongs fasting without benefit and risks dehydration and hypoglycaemia; 08:00 is the 2-hour clear-fluid rule, which does not apply to milk."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Mixed Acid-Base Disorder","stem":"A septic patient who is tiring has pH 7.02, HCO3- 10 mmol/L and PaCO2 40 mmHg. Using Winter's formula (expected PaCO2 = 1.5 x HCO3- + 8, plus or minus 2), what is the acid-base disorder?","options":["Pure respiratory acidosis","Metabolic acidosis with an additional respiratory alkalosis","Metabolic acidosis with an additional respiratory acidosis","Metabolic acidosis with appropriate respiratory compensation"],"correct":2,"explanation":"Expected PaCO2 = 1.5 x 10 + 8 = 23 (range 21-25 mmHg); the actual PaCO2 of 40 is much higher, so the patient is not breathing off enough CO2 and has a second, respiratory acidosis, often a sign of exhaustion needing ventilatory support. A 'normal' PaCO2 of 40 is a common trap that hides this."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Post-Tonsillectomy Bleeding","stem":"A 6-year-old is brought back 5 hours after tonsillectomy. He is pale, swallowing blood, HR 150/min, capillary refill 4 seconds. What is the safest anaesthetic plan?","options":["Inhalational induction, then insert a laryngeal mask airway","Give a sedative and let the surgeon pack the tonsil bed awake","Restore circulating volume via IV access, then rapid sequence induction with two suctions ready","Delay surgery until the haemoglobin result is available"],"correct":2,"explanation":"The child is hypovolaemic and has a stomach full of blood, so resuscitate first, then use rapid sequence induction with good suction and an experienced assistant. A laryngeal mask does not protect against aspiration of blood, and the Hb is unreliable in acute bleeding."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Pyloric Stenosis Electrolytes","stem":"A 6-week-old baby has had projectile, non-bile-stained vomiting for 5 days and is booked for pyloromyotomy. Which acid-base and electrolyte picture is expected?","options":["Acute respiratory alkalosis with hyperkalaemia","Hyperchloraemic metabolic acidosis","Hypochloraemic, hypokalaemic metabolic alkalosis","High anion gap metabolic acidosis"],"correct":2,"explanation":"Repeated vomiting of gastric acid loses H+ and Cl-, and the kidney then wastes K+, giving a hypochloraemic, hypokalaemic metabolic alkalosis. This must be corrected with IV fluids before anaesthesia, because pyloric stenosis is a medical, not surgical, emergency."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Interscalene Block Risks","stem":"A 70-year-old man with severe COPD on home oxygen needs shoulder surgery. Why is an interscalene brachial plexus block risky for him?","options":["It almost always blocks the phrenic nerve, paralysing half the diaphragm","It commonly causes pneumothorax in COPD patients","It often causes bronchospasm by blocking the vagus nerve","It blocks the intercostal nerves of the upper chest"],"correct":0,"explanation":"The phrenic nerve (C3–C5) runs on the anterior scalene, so interscalene block nearly always causes same-side diaphragm paralysis, which patients with severe lung disease may not tolerate. Pneumothorax is mainly a risk of the supraclavicular approach."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Saline-Induced Acidosis","stem":"During a long laparotomy, a patient receives 6 litres of 0.9% sodium chloride. The gas then shows pH 7.30, HCO3- 18 mmol/L, Cl- 118 mmol/L, normal anion gap and normal lactate. What is the most likely cause?","options":["Respiratory acidosis from under-ventilation","Lactic acidosis from poor tissue perfusion","Hyperchloraemic acidosis from the large volume of saline","Ketoacidosis from preoperative fasting"],"correct":2,"explanation":"0.9% saline contains much more chloride than plasma, and large volumes cause a normal anion gap (hyperchloraemic) metabolic acidosis; balanced solutions such as Ringer's lactate reduce this. Lactic acidosis and ketoacidosis both raise the anion gap, which is normal here."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Horner's Syndrome After Block","stem":"An hour after a left interscalene block, a patient has a droopy left eyelid and a small left pupil. He is otherwise well. What is the best management?","options":["Reassure: spread to the cervical sympathetic chain, which wears off","Give 20% lipid emulsion for local anaesthetic toxicity","Request an urgent CT head to exclude a stroke","Give IV steroids for nerve injury to the face"],"correct":0,"explanation":"Ptosis and miosis on the same side are Horner's syndrome from spread of local anaesthetic to the cervical sympathetic chain, a common harmless side effect that resolves with the block. Local anaesthetic toxicity causes CNS and heart signs, not a one-sided eye change."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Hyperventilation and Tingling","stem":"An anxious woman waiting for surgery breathes rapidly and complains of tingling fingers and spasm of her hands. Gas: pH 7.57, PaCO2 25 mmHg (3.3 kPa), HCO3- 22 mmol/L. What explains the findings?","options":["Respiratory acidosis, with symptoms caused by high CO2","Compensated metabolic acidosis, caused by low sodium","Metabolic alkalosis, with symptoms caused by low potassium","Acute respiratory alkalosis, which lowers ionised calcium"],"correct":3,"explanation":"High pH with a low PaCO2 and normal bicarbonate is acute respiratory alkalosis from hyperventilation; alkalosis makes more calcium bind to albumin, lowering ionised calcium and causing tingling and carpopedal spasm. In metabolic alkalosis the bicarbonate would be raised."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Supraclavicular Block Complications","stem":"Shortly after a supraclavicular brachial plexus block, a patient develops a cough, pleuritic chest pain and increasing shortness of breath. What complication is most likely?","options":["Recurrent laryngeal nerve block","Local anaesthetic toxicity","Phrenic nerve palsy","Pneumothorax"],"correct":3,"explanation":"The pleura lies just below the plexus over the first rib, so pneumothorax is the classic complication of the supraclavicular approach (less likely with ultrasound). Phrenic palsy can cause breathlessness but not cough with pleuritic pain."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Air Bubble in Gas Sample","stem":"An arterial blood sample is analysed with a large air bubble left in the syringe. Which error in the result is most likely?","options":["Potassium falsely low","PaCO2 falsely high","PaCO2 falsely low","Bicarbonate falsely high"],"correct":2,"explanation":"Room air contains almost no CO2, so CO2 moves out of the blood into the bubble and the measured PaCO2 falls (and the PaO2 moves towards that of room air). A falsely high PaCO2 is more typical of a sample left too long at room temperature, when cells keep producing CO2."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Axillary Block Coverage","stem":"After an axillary brachial plexus block, the patient can still bend his elbow strongly and feels touch on the lateral (radial) side of his forearm. Which nerve has been missed?","options":["Radial nerve","Ulnar nerve","Musculocutaneous nerve","Median nerve"],"correct":2,"explanation":"The musculocutaneous nerve leaves the sheath high and runs in coracobrachialis; it supplies biceps and brachialis (elbow flexion) and the skin of the lateral forearm, so it must be blocked separately. The radial nerve mainly supplies extension and the back of the arm and forearm."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Chronic Respiratory Acidosis","stem":"A 66-year-old with severe COPD is clinically stable before an elective hernia repair. Arterial gas on air: pH 7.35, PaCO2 60 mmHg (8 kPa), HCO3- 32 mmol/L. What does this show?","options":["Chronic respiratory acidosis with renal compensation","Acute respiratory acidosis","Metabolic alkalosis with respiratory compensation","Combined respiratory and metabolic acidosis"],"correct":0,"explanation":"The pH is on the acid side, PaCO2 is high and HCO3- is raised as expected for chronic compensation: about 3.5-4 mmol/L per 10 mmHg rise in PaCO2, so 24 + (2 x 3.5 to 4) = 31-32 mmol/L. In acute respiratory acidosis HCO3- rises only about 1 mmol/L per 10 mmHg (about 26 mmol/L here) with a much lower pH, a primary metabolic alkalosis would give an alkaline pH, and a metabolic acidosis would lower, not raise, the HCO3-."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Brachial Plexus Approach Choice","stem":"A patient needs surgery on the little finger (ulnar side of the hand). Which brachial plexus approach is LEAST likely to give a complete block?","options":["Infraclavicular","Interscalene","Supraclavicular","Axillary"],"correct":1,"explanation":"The interscalene approach targets the upper and middle trunks (C5–C7) and often spares the inferior trunk (C8–T1), which forms the ulnar nerve. Supraclavicular, infraclavicular and axillary approaches reliably cover the ulnar nerve."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Paediatric Paracetamol Dose","stem":"A 14 kg child needs oral paracetamol after hernia repair. The prescribed dose is 15 mg/kg, and the syrup is 120 mg per 5 mL. What volume should be given?","options":["10.5 mL","4.4 mL","8.75 mL","17.5 mL"],"correct":2,"explanation":"Dose = 14 kg x 15 mg/kg = 210 mg; volume = 210 / 120 x 5 mL = 8.75 mL. 17.5 mL would be a double (30 mg/kg) dose."},
    ],
  },
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-anaesthesia-licensing-exam","name":"Anaesthesia Licensing Exam (RAHPC)"},
    slug: "rahpc-anaesthesia-mock-exam-5",
    title: "Anaesthesia Licensing Exam (RAHPC) — Mock Exam 5",
    summary: "Anaesthetic Pharmacology and General Anaesthesia; Regional Anaesthesia, Critical Care and Resuscitation.",
    free: false, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover anaesthesia practice."],
    sections: [{"name":"Anaesthetic Pharmacology and General Anaesthesia"},{"name":"Regional Anaesthesia, Critical Care and Resuscitation"}],
    questions: [
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"MH Safe Drugs","stem":"A 22-year-old whose brother had malignant hyperthermia needs a general anaesthetic and is treated as MH-susceptible. Which drug is safe to use?","options":["Sevoflurane","Propofol","Suxamethonium","Isoflurane"],"correct":1,"explanation":"MH is triggered by volatile agents (halothane, isoflurane, sevoflurane, desflurane) and suxamethonium. Propofol, opioids, nitrous oxide, non-depolarising relaxants and local anaesthetics are safe, so a TIVA or regional technique is used."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Arterial to End-Tidal Gap","stem":"In a healthy ventilated adult, the end-tidal CO2 is usually a few mmHg lower than the arterial PaCO2. What is the main reason?","options":["Carbon dioxide is produced inside the breathing circuit","The capnograph measures inspired rather than expired gas","Alveolar dead space dilutes CO2 from perfused alveoli","CO2 is absorbed into the wall of the tracheal tube"],"correct":2,"explanation":"Expired gas mixes CO2-rich gas from perfused alveoli with CO2-free gas from ventilated but unperfused alveoli (alveolar dead space), so end-tidal CO2 is normally about 2-5 mmHg lower than PaCO2. The gap widens when dead space increases, for example with low cardiac output or pulmonary embolism."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"MH First Actions","stem":"During a laparotomy under isoflurane, end-tidal CO2 rises fast, HR is 140/min and the muscles are stiff. You suspect malignant hyperthermia. What should you do first?","options":["Change the soda lime and continue the isoflurane","Wait for the temperature to rise to confirm the diagnosis","Give paracetamol and start cooling with ice packs","Stop isoflurane, call for help and hyperventilate with 100% O2"],"correct":3,"explanation":"MHAUS: stop all trigger agents, call for help and dantrolene, and hyperventilate with 100% oxygen at high fresh-gas flow, then give dantrolene 2.5 mg/kg. Waiting for a high temperature delays treatment, because hyperthermia is often a late sign."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Recovery Airway Obstruction","stem":"In the recovery room, a drowsy patient after general anaesthesia is snoring, with the chest moving but little air moving at the mouth. SpO2 is 89%. What should the recovery nurse do first?","options":["Sit the patient up and give a salbutamol nebuliser","Give naloxone 400 micrograms IV straight away","Perform a jaw thrust or chin lift and give oxygen","Call the surgeon to come and review the wound"],"correct":2,"explanation":"Snoring with chest movement but little airflow means the tongue and soft tissues are blocking the upper airway; a jaw thrust or chin lift with oxygen opens it, and an oropharyngeal or nasopharyngeal airway can follow. Naloxone may be needed later if opioids are the cause, but the airway is opened first."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Dantrolene Dose","stem":"An 80 kg man has malignant hyperthermia. Dantrolene is available in 20 mg vials. How many vials are needed for the recommended initial dose?","options":["4 vials","10 vials","20 vials","5 vials"],"correct":1,"explanation":"The initial dose is 2.5 mg/kg: 2.5 x 80 = 200 mg; 200 / 20 = 10 vials, each mixed with 60 mL sterile water. Doses are repeated until signs settle; 4 vials would be only 1 mg/kg, which is the later maintenance dose."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Laryngospasm After Extubation","stem":"Immediately after extubation, a 6-year-old develops a high-pitched inspiratory noise, then silent chest movements with a falling SpO2. What is the first management?","options":["Reintubate at once using a smaller tracheal tube","Give salbutamol through a spacer and face mask","Give IV hydrocortisone and observe the child closely","100% oxygen by tight face mask with CPAP and jaw thrust"],"correct":3,"explanation":"This is laryngospasm: remove the stimulus, give 100% oxygen with continuous positive pressure through a tight mask and apply a firm jaw thrust. If it does not settle, deepen anaesthesia with propofol and give suxamethonium if needed; steroids and bronchodilators do not relieve laryngospasm."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Dantrolene Mechanism","stem":"How does dantrolene treat malignant hyperthermia?","options":["Binds and removes potassium from the blood","Blocks acetylcholine at the motor end-plate","Lowers the temperature set point in the hypothalamus","Reduces calcium release from muscle stores via RyR1"],"correct":3,"explanation":"MH is caused by uncontrolled calcium release through abnormal ryanodine (RyR1) receptors in skeletal muscle; dantrolene acts on the ryanodine receptor to reduce this release. It is not a neuromuscular blocker, and fever drugs acting on the hypothalamus do not help."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Residual Neuromuscular Block","stem":"A woman in recovery after laparoscopy received rocuronium, and no reversal was given. She is awake but has weak, jerky movements, cannot lift her head, and has shallow 'see-saw' breathing. What is the best action?","options":["Give IV midazolam to settle her agitated movements","Give naloxone for opioid-induced breathing depression","Reassure her and recheck her breathing in one hour","Give oxygen, support breathing and give a reversal agent"],"correct":3,"explanation":"These are signs of residual neuromuscular block; she needs oxygen, breathing support if required and reversal (neostigmine with glycopyrrolate, or sugammadex for rocuronium), ideally guided by a nerve stimulator. Opioid excess causes a drowsy patient with slow breathing and small pupils, not an awake patient with weak, jerky movements."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Drugs To Avoid In MH","stem":"A patient being treated with dantrolene for malignant hyperthermia develops arrhythmias and hyperkalaemia. Which drug should be avoided?","options":["Amiodarone","Insulin with glucose","Calcium chloride","Verapamil"],"correct":3,"explanation":"MHAUS advises against calcium channel blockers such as verapamil with dantrolene, as the combination can cause severe hyperkalaemia and cardiovascular collapse. Hyperkalaemia is treated with calcium, insulin with glucose and hyperventilation, and amiodarone may be used for arrhythmias."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Rescue Treatment for PONV","stem":"A woman given ondansetron 4 mg at induction vomits repeatedly in recovery 1 hour after a laparoscopy. Pain, hypotension and hypoxia have been excluded. What is the best treatment?","options":["Repeat ondansetron 4 mg IV now","Withhold drugs and wait 2 hours for it to settle","Give ondansetron 8 mg IV, a double dose","Give an antiemetic from a different class, such as cyclizine"],"correct":3,"explanation":"Consensus guidelines advise rescue treatment with an antiemetic from a different class from the one used for prophylaxis, because repeating a 5-HT3 antagonist within about 6 hours adds little benefit. A larger ondansetron dose does not overcome this, and leaving repeated vomiting untreated risks dehydration, wound strain and aspiration."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Machine Preparation For MH","stem":"An MH-susceptible patient is first on tomorrow's list. How should the anaesthetic machine be prepared?","options":["Give the patient dantrolene before induction","Keep vaporisers but use sevoflurane at a low setting","Change only the face mask; keep the old circuit","Remove vaporisers; flush with high-flow O2 or fit charcoal filters"],"correct":3,"explanation":"Volatile agent left in the machine can trigger MH, so vaporisers are removed or disabled, the circuit and absorbent changed, and the machine flushed at high flow as the manufacturer advises (or activated charcoal filters fitted). Even low concentrations of volatile agents can trigger MH, and prophylactic dantrolene is not recommended."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Recovery Room Discharge","stem":"A recovery nurse uses the modified Aldrete score to decide when a patient may leave the recovery room. Which total score is usually needed for discharge to the ward?","options":["5 or more out of 10","9 or more out of 10","10 out of 10 only","7 or more out of 10"],"correct":1,"explanation":"The modified Aldrete score rates activity, breathing, circulation, consciousness and oxygen saturation from 0 to 2 each, and 9 or more is the usual discharge criterion. Insisting on 10 would hold back patients with small, acceptable deficits."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Care After An MH Crisis","stem":"A patient's malignant hyperthermia crisis has settled after dantrolene. What is the most appropriate next step?","options":["Send to the ward once the temperature is normal","Stop monitoring once end-tidal CO2 is normal","Admit to ICU for at least 24 hours and watch for recurrence","Restart the volatile agent at a lower concentration"],"correct":2,"explanation":"MH can return (recrudescence) in about 1 in 5 patients, usually within the first day, so MHAUS advises ICU observation for at least 24 hours with continued dantrolene (1 mg/kg every 4 to 6 hours or 0.25 mg/kg/hour). The patient and family are then referred for counselling and testing."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Postoperative Shivering","stem":"A patient in recovery is shivering strongly after a long operation, and his temperature is 35.2 degrees C. Why is it important to treat this promptly?","options":["Shivering lowers the blood pressure and slows the heart dangerously","Shivering is the earliest sign of malignant hyperthermia in recovery","Shivering greatly increases oxygen use and can cause hypoxia or ischaemia","Shivering shows that the opioid dose given in theatre was too high"],"correct":2,"explanation":"Shivering sharply increases oxygen consumption, which can stress patients with heart or lung disease; treat with oxygen, active warming (for example a forced-air blanket) and, if needed, a small dose of pethidine. Malignant hyperthermia causes a rising temperature with rigidity, not shivering from cold."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Lidocaine Maximum Volume","stem":"A 70 kg man needs a field block with 1% lidocaine with adrenaline. Using a maximum dose of 7 mg/kg, what is the largest volume you may inject?","options":["49 mL","4.9 mL","21 mL","24.5 mL"],"correct":0,"explanation":"Maximum dose = 7 x 70 = 490 mg. 1% = 1 g in 100 mL = 10 mg/mL, so 490 / 10 = 49 mL. 24.5 mL comes from wrongly taking 1% as 20 mg/mL, and 21 mL is the limit for plain lidocaine at 3 mg/kg."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Post-Extubation Stridor","stem":"A 3-year-old develops a barking cough and inspiratory stridor 30 minutes after extubation. SpO2 is 94% on oxygen and he is not tiring. What is the most appropriate treatment?","options":["IV furosemide to treat pulmonary oedema","Nebulised adrenaline with humidified oxygen and dexamethasone","Immediate reintubation with a larger tracheal tube","Nebulised salbutamol every 20 minutes"],"correct":1,"explanation":"Post-extubation croup is caused by swelling below the vocal cords, often from a tight tube; nebulised adrenaline reduces the swelling quickly and dexamethasone reduces recurrence. A larger tube would worsen the swelling, and salbutamol treats bronchospasm, not subglottic oedema."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Bupivacaine Maximum Volume","stem":"A 60 kg woman is to have a nerve block with 0.5% bupivacaine. Using a maximum dose of 2 mg/kg, what is the largest volume you may give?","options":["12 mL","2.4 mL","24 mL","48 mL"],"correct":2,"explanation":"Maximum dose = 2 x 60 = 120 mg. 0.5% = 5 mg/mL, so 120 / 5 = 24 mL. 12 mL comes from wrongly taking 0.5% as 10 mg/mL, and 48 mL would be the volume of 0.25% bupivacaine."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"PONV Risk Assessment","stem":"Which patient has the highest risk of postoperative nausea and vomiting using the simplified Apfel score?","options":["A male smoker having day-case surgery who will need no opioids afterwards","A non-smoking woman with motion sickness who will need morphine after surgery","A female smoker with no previous PONV who will need no opioids afterwards","A non-smoking man having surgery who will need only paracetamol afterwards"],"correct":1,"explanation":"The simplified Apfel score gives 1 point each for female sex, non-smoking, previous PONV or motion sickness, and postoperative opioids, so she scores 4 (about 80% risk). The man who smokes scores 0, and the other two score 1 each."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Percentage To Milligrams","stem":"Before inserting a large cannula, you infiltrate 5 mL of 2% lidocaine. How many milligrams of lidocaine have you given?","options":["1000 mg","100 mg","50 mg","10 mg"],"correct":1,"explanation":"2% = 2 g in 100 mL = 20 mg/mL, so 5 mL x 20 mg/mL = 100 mg. 10 mg comes from reading 2% as 2 mg/mL."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Delayed Emergence","stem":"A 60-year-old diabetic man has not woken 40 minutes after a short anaesthetic. His airway is clear and he is breathing well, the volatile agent was stopped long ago, the train-of-four ratio is above 0.9 and he received little opioid. What should be done first?","options":["Arrange an urgent CT scan of the head","Repeat the dose of neostigmine","Give flumazenil and wait","Check his capillary blood glucose"],"correct":3,"explanation":"Hypoglycaemia is a common and quickly reversible cause of delayed waking, especially in diabetic patients, so a capillary glucose is checked as soon as airway and breathing are secure. More neostigmine will not help when the TOF ratio is already above 0.9, and a CT scan is considered only after simple metabolic and drug causes are excluded."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Adrenaline Ratio Strength","stem":"A local anaesthetic solution contains adrenaline 1 in 200,000. How much adrenaline is in 20 mL?","options":["100 micrograms","200 micrograms","1 milligram","10 micrograms"],"correct":0,"explanation":"1 in 200,000 = 1 g in 200,000 mL = 1,000,000 micrograms / 200,000 mL = 5 micrograms/mL. 20 mL x 5 micrograms/mL = 100 micrograms. 200 micrograms would be the amount in 20 mL of a 1 in 100,000 solution."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Propofol Induction Volume","stem":"A 65 kg woman is to be induced with 1% propofol at 2 mg/kg. What volume should you draw up?","options":["1.3 mL","6.5 mL","13 mL","26 mL"],"correct":2,"explanation":"Dose = 2 x 65 = 130 mg. 1% propofol = 10 mg/mL, so 130 / 10 = 13 mL. 6.5 mL would be the volume of 2% propofol (20 mg/mL)."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"IV Drip Rate","stem":"A patient in theatre needs 500 mL of Ringer's lactate over 4 hours using a giving set that delivers 20 drops/mL. What is the drip rate?","options":["About 125 drops/min","About 83 drops/min","About 42 drops/min","About 21 drops/min"],"correct":2,"explanation":"Drops/min = volume x drop factor / time in minutes = 500 x 20 / (4 x 60) = 10,000 / 240 = 41.7, about 42 drops/min. 125 is the rate in mL per hour (500 / 4), not drops per minute."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Paediatric Atropine Dose","stem":"A 15 kg child needs atropine 20 micrograms/kg IV. The ampoule contains 600 micrograms in 1 mL. What volume should you give?","options":["5 mL","0.05 mL","0.3 mL","0.5 mL"],"correct":3,"explanation":"Dose = 20 x 15 = 300 micrograms. 300 / 600 micrograms per mL = 0.5 mL. 0.3 mL comes from confusing the dose in milligrams (0.3 mg) with the volume in mL."},
      {"section":"Anaesthetic Pharmacology and General Anaesthesia","topic":"Suxamethonium Dose For RSI","stem":"For a rapid sequence induction in an 80 kg man, you plan suxamethonium 1.5 mg/kg. The ampoule is 100 mg in 2 mL. What volume should you give?","options":["1.6 mL","12 mL","2.4 mL","4.8 mL"],"correct":2,"explanation":"Dose = 1.5 x 80 = 120 mg. 100 mg in 2 mL = 50 mg/mL, so 120 / 50 = 2.4 mL. 1.6 mL would be a 1 mg/kg dose (80 mg / 50)."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Femoral Nerve Anatomy","stem":"On ultrasound at the inguinal crease, where is the femoral nerve found in relation to the femoral artery?","options":["Medial to the femoral vein","Directly between the artery and the vein","Deep to the femoral vein","Lateral to the artery, beneath the fascia iliaca"],"correct":3,"explanation":"From lateral to medial the order is nerve, artery, vein (NAV); the nerve lies lateral to the artery under the fascia iliaca, outside the femoral sheath. The space medial to the vein contains lymphatics (femoral canal), not the nerve."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Early Sign of Opioid Toxicity","stem":"A post-operative patient receiving morphine is on 2 L/min of oxygen by nasal cannula. Which observation gives the most reliable early warning of opioid-induced respiratory depression?","options":["A falling SpO2","Increasing sedation, hard to rouse","Small pupils","Itching of the face"],"correct":1,"explanation":"Rising sedation usually comes before dangerous respiratory depression, so a sedation score is recorded with the respiratory rate. In a patient on oxygen, SpO2 can stay normal until CO2 is very high, so a falling SpO2 is a late sign."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Hip Fracture Analgesia","stem":"An 84-year-old woman with a fractured neck of femur is in severe pain in the emergency department. Which regional technique is most suitable for early analgesia?","options":["Fascia iliaca compartment block","Adductor canal block","Ankle block","Popliteal sciatic nerve block"],"correct":0,"explanation":"A fascia iliaca block spreads to the femoral nerve (and often the lateral cutaneous nerve of the thigh), which supply much of the hip, reducing opioid needs and delirium risk. An adductor canal block covers mainly the saphenous nerve below the knee, so it does not help a hip fracture."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Opioid Constipation","stem":"A patient will take regular oral morphine for several weeks after major orthopaedic surgery. Which side effect shows little or no tolerance with continued use, so it needs prevention from the start?","options":["Nausea and vomiting","Sedation","Respiratory depression","Constipation"],"correct":3,"explanation":"Tolerance develops over days to the sedation, nausea and respiratory depression caused by opioids, but hardly at all to constipation (or small pupils), so a regular laxative is prescribed together with the morphine. Nausea often settles within the first week, which is why antiemetics are usually needed only at the start."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Ankle Block Nerves","stem":"An ankle block anaesthetises five nerves. Which one is a branch of the femoral nerve rather than the sciatic nerve?","options":["Saphenous nerve","Posterior tibial nerve","Deep peroneal nerve","Sural nerve"],"correct":0,"explanation":"The saphenous nerve is the terminal branch of the femoral nerve and supplies the medial ankle and foot. The sural, deep peroneal, superficial peroneal and posterior tibial nerves all come from the sciatic nerve."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"NSAID Contraindication","stem":"A 45-year-old man is booked for hernia repair. Which item in his history most strongly argues against giving diclofenac for post-operative pain?","options":["Asthma that became worse after taking aspirin","Nausea after codeine in the past","Well-controlled hypothyroidism","A rash with penicillin in the past"],"correct":0,"explanation":"Patients with aspirin-sensitive asthma can have severe bronchospasm with other NSAIDs such as diclofenac, which also share the COX-1 effect. Penicillin allergy and codeine nausea are unrelated to NSAIDs; other major cautions are renal impairment, peptic ulcer and bleeding risk."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Preventing LAST","stem":"You are about to inject 30 mL of 0.5% bupivacaine for a supraclavicular block under ultrasound. Which injection technique best reduces the risk of local anaesthetic systemic toxicity?","options":["Rely on one negative aspiration test before injecting","Inject the full volume quickly so the block works sooner","Inject continuously without stopping, to keep the needle still","Inject in small increments of 3-5 mL, aspirating between doses"],"correct":3,"explanation":"ASRA advises injecting in increments of 3 to 5 mL with a pause and gentle aspiration between them, while watching the patient for early toxic signs and using the lowest effective dose. A single negative aspiration does not exclude intravascular placement because false negatives occur, and a rapid continuous injection can deliver a toxic dose before any warning sign appears."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Oral Morphine Bioavailability","stem":"A patient comfortable on IV morphine is changed to oral morphine and needs a larger oral dose for the same pain relief. Why?","options":["Food in the gut binds the morphine and inactivates it","Stomach acid destroys most of the oral dose","Most of the oral dose is excreted unchanged in the stool","Much of the oral dose is broken down by the liver before reaching the circulation"],"correct":3,"explanation":"After absorption from the gut, morphine passes through the liver, where a large part is glucuronidated before it reaches the systemic circulation (first-pass metabolism); oral bioavailability is only about 20-40%, so oral doses are about 2 to 3 times the IV dose. Morphine is well absorbed from the gut and is not destroyed by stomach acid."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Ropivacaine Versus Bupivacaine","stem":"Why is ropivacaine often chosen instead of racemic bupivacaine for a large-volume peripheral nerve block?","options":["It is a pure S-enantiomer with less cardiotoxicity","It has a much faster onset than lidocaine","It has no maximum safe dose","It is an ester, so it carries no risk of toxicity"],"correct":0,"explanation":"Ropivacaine is a pure S-enantiomer and is less cardiotoxic than racemic bupivacaine at similar doses, so it is safer for high-volume blocks, although it can still cause LAST in overdose. It is an amide, not an ester, its onset is not faster than lidocaine's, and like every local anaesthetic it has a maximum safe dose."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Patient-Controlled Analgesia Safety","stem":"A patient after a laparotomy is started on a morphine PCA pump. Which instruction is most important for safety?","options":["The nurse should press the button every 10 minutes","Relatives should press the button when the patient is asleep","Only the patient should press the button","The patient should press only when the pain score reaches 10/10"],"correct":2,"explanation":"PCA is safe because a patient who becomes too sedated stops pressing the button; if relatives or staff press it, this protection is lost and overdose can occur. The patient should press whenever the pain is troublesome, not wait for severe pain."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Local Anaesthetic Duration","stem":"Bupivacaine acts much longer than lidocaine. Which property mainly explains its longer duration of action?","options":["Its smaller molecule size","Its higher pKa","Slower breakdown by plasma cholinesterase","Its higher degree of protein binding"],"correct":3,"explanation":"Duration of action rises with protein binding (bupivacaine about 95%, lidocaine about 65%), because a highly bound drug stays bound in the nerve membrane for longer; lipid solubility mainly determines potency. pKa determines the speed of onset, and both drugs are amides broken down in the liver, not by plasma cholinesterase."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Codeine in Children","stem":"A 5-year-old has had a tonsillectomy for obstructive sleep apnoea. Why is codeine avoided for this child's pain?","options":["Codeine blocks platelets and increases bleeding from the tonsil bed","Codeine can cause Reye's syndrome in children","Codeine is too weak to have any analgesic effect","Some children convert codeine rapidly to morphine and can stop breathing"],"correct":3,"explanation":"Codeine works after conversion to morphine by CYP2D6, and children who are ultra-rapid metabolisers can produce high morphine levels and die of respiratory depression, especially after tonsillectomy for sleep apnoea. Reye's syndrome is linked to aspirin, not codeine."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Local Anaesthetic Absorption","stem":"The same dose of local anaesthetic is used for different blocks. Which block produces the highest peak blood level, and so the greatest risk of toxicity?","options":["Intercostal nerve block","Brachial plexus block","Subcutaneous infiltration","Femoral–sciatic block"],"correct":0,"explanation":"Absorption depends on the blood supply of the site: intercostal > caudal > epidural > brachial plexus > sciatic/femoral > subcutaneous. So intercostal blocks give the highest blood levels for the same dose."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Pain Assessment in Toddlers","stem":"An 18-month-old child is in the recovery room after a hernia repair. Which tool is most suitable for assessing the child's pain?","options":["A 0-10 numerical rating scale","A 10 cm visual analogue scale","The FLACC behavioural scale","The Wong-Baker faces scale"],"correct":2,"explanation":"FLACC (Face, Legs, Activity, Cry, Consolability) scores observed behaviour and suits young children who cannot describe their pain. Faces scales need a child of about 3 years or more to choose a face, and numerical or visual scales need an older child."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Intravenous Regional Anaesthesia","stem":"A Bier's block (IV regional anaesthesia) with prilocaine is used to reduce a forearm fracture. The reduction is finished 10 minutes after injection and the surgeon asks you to release the tourniquet. What should you do?","options":["Keep the cuff inflated until at least 20 minutes after injection","Deflate and reinflate the cuff quickly every minute from now","Release the cuff and inject more prilocaine if pain returns","Release the cuff at once, as the procedure is done"],"correct":0,"explanation":"The cuff must stay inflated for at least 20 minutes after injection so that enough drug binds to the tissues; early release sends a large bolus into the circulation and can cause toxicity. Bupivacaine must never be used for this block because of its cardiotoxicity."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Antibiotic Check Timing","stem":"In the WHO Surgical Safety Checklist, at which phase does the team confirm that antibiotic prophylaxis has been given within the last 60 minutes?","options":["Sign In, before induction of anaesthesia","Sign Out, before the patient leaves theatre","In the recovery room, after surgery","Time Out, before the skin incision"],"correct":3,"explanation":"The antibiotic question is part of Time Out, just before the skin incision, so that the drug is in the tissues when the incision is made. Sign In covers identity, site marking, the anaesthesia check, pulse oximeter, allergies, airway and blood-loss risk."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Nerve Stimulator Technique","stem":"Using a peripheral nerve stimulator (0.1 ms pulse), you get a good muscle twitch at 0.5 mA. You turn the current down and the twitch is still present at 0.2 mA. What should you do?","options":["Increase the current to 1.5 mA and inject","Inject the full dose quickly at this position","Advance the needle further to get a stronger twitch","Withdraw the needle slightly before injecting"],"correct":3,"explanation":"A twitch at 0.2 mA or less suggests the needle is very close to or inside the nerve, so withdraw slightly until the twitch is lost at 0.2 mA but present at about 0.5 mA. Injecting here or advancing risks intraneural injection and nerve injury."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Sign Out Items","stem":"Using the WHO Surgical Safety Checklist, which item is reviewed at Sign Out, before the patient leaves the operating room?","options":["The patient's known allergies","Whether the operation site is marked","Whether essential imaging is displayed","Key concerns for the recovery and management of the patient"],"correct":3,"explanation":"At Sign Out the nurse confirms the procedure name, counts, specimen labelling and any equipment problems, and the surgeon, anaesthetist and nurse review the key concerns for the patient's recovery and management. Allergies and site marking are checked at Sign In, and the display of essential imaging is confirmed at Time Out."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Local Anaesthetic Pharmacology","stem":"Local infiltration for draining a large abscess works poorly. What is the main reason?","options":["The acidic tissue increases the ionised fraction, so less drug crosses the nerve membrane","Inflamed tissue has fewer sodium channels for the drug to block","Infection increases plasma cholinesterase, which breaks the drug down","Pus physically blocks the drug from reaching the nerve fibres"],"correct":0,"explanation":"Local anaesthetics are weak bases; only the un-ionised form crosses the nerve membrane, and acidic infected tissue increases the ionised fraction. Lidocaine is an amide metabolised in the liver, so plasma cholinesterase is not the reason."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Airway Risk at Sign In","stem":"At Sign In, the anaesthetist answers 'yes' to the question 'Does the patient have a difficult airway or aspiration risk?'. What does the checklist then require before induction?","options":["Give the antibiotic prophylaxis straight away","Confirm that equipment and assistance are available","Ask the surgeon to re-mark the operation site","Cancel the operation and refer the patient"],"correct":1,"explanation":"If a difficult airway or aspiration risk is identified at Sign In, the checklist requires the team to confirm that the right equipment and a skilled assistant are present before induction. The risk alone is not a reason to cancel, and antibiotic timing is confirmed at Time Out."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Missing Swab at Sign Out","stem":"At the end of an operation, the scrub nurse reports that one abdominal swab is missing from the count. What should happen according to the WHO Surgical Safety Checklist?","options":["Report it at the next morning's Time Out for the following patient","Record it at Sign Out and send the patient to recovery, then look for the swab","Do nothing, since counts are only checked at Sign In","Resolve it at Sign Out by searching, with an X-ray if needed, before the patient leaves theatre"],"correct":3,"explanation":"The swab, sharps and instrument counts are confirmed at Sign Out, and any mismatch must be resolved (wound and room search, X-ray if needed) before the patient leaves theatre. Sending the patient out first defeats the purpose of the check."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Checklist Coordinator","stem":"According to the WHO Implementation Manual, who should lead (coordinate) the Surgical Safety Checklist in theatre?","options":["Any staff member who is free, with no single person responsible","One designated team member, often the circulating nurse","The anaesthetist only, at the end of the operation","The surgeon only, as the person responsible for the operation"],"correct":1,"explanation":"WHO recommends that a single designated person, usually the circulating nurse, leads the checklist and confirms each step with the team, while all members share responsibility. Having nobody clearly responsible is a common reason steps are missed."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Confirmation at Time Out","stem":"During Time Out, just before incision, who should verbally confirm the patient's identity, the operation site and the procedure?","options":["The patient, who is already anaesthetised","The surgeon, the anaesthesia professional and the nurse","The circulating nurse alone, reading from the notes","The surgeon alone, as he has seen the patient"],"correct":1,"explanation":"At Time Out the surgeon, anaesthesia professional and nurse together confirm the patient, site and procedure aloud, so that any one member can spot an error. Confirmation by the patient is done at Sign In, before induction, when the patient is still awake."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Anaesthetist's Time Out Role","stem":"During Time Out, the team reviews anticipated critical events. What is the anaesthesia professional's part in this review?","options":["Confirming the sterility indicator results of the instruments","Stating any patient-specific concerns, such as airway or comorbidity","Confirming the swab and instrument counts are correct","Stating the critical surgical steps and expected duration"],"correct":1,"explanation":"At Time Out the anaesthesia professional states patient-specific concerns (for example difficult airway, heart disease, blood availability). The surgeon describes critical steps, duration and expected blood loss, and the nurse confirms sterility and equipment issues."},
      {"section":"Regional Anaesthesia, Critical Care and Resuscitation","topic":"Identity Check Without Patient","stem":"At Sign In, a 70-year-old man with advanced dementia cannot confirm his name or the planned operation. What is the best action?","options":["Confirm identity, site, procedure and consent with a family member or guardian and the records","Proceed because the surgeon says he recognises the patient","Skip the identity check because the ward nurse brought him","Cancel the operation until the patient can confirm it himself"],"correct":0,"explanation":"When the patient cannot confirm the details, WHO advises that a family member or guardian confirms identity, site, procedure and consent, checked against the wristband and records. Skipping the check or relying on one person's memory removes the safeguard, and cancelling is unnecessary."},
    ],
  },
];
